-- 2. Questions ------------------------------------------------------------
-- Rangées APRÈS celles du quiz : position = dernière position + rang.
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, qz.id, v.question, v.kind, v.options, v.correct_index, v.explanation,
       COALESCE((SELECT max(x.position) FROM public.quiz_questions x WHERE x.quiz_id = qz.id), 0) + v.rang
  FROM (VALUES
    ('29322e3b-3a89-5899-8587-ce067af62097'::uuid, 'allemand', '5e', 'Se présenter et saluer', 'Comment demande-t-on son nom à un professeur, en le vouvoyant ?', 'mcq', '["Wie heißt du ?","Wie heißen Sie ?","Wie heiße Sie ?","Wie bist Sie ?"]'::jsonb, 1, 'Avec « Sie », le verbe prend la terminaison -en : « Wie heißen Sie ? ». « Wie heißt du ? » sert pour tutoyer.', 1),
    ('5090b6a4-bfe4-528d-84f9-51c5c00aca2a'::uuid, 'allemand', '5e', 'Se présenter et saluer', 'Quelle formule utilise-t-on pour dire au revoir poliment à un adulte ?', 'mcq', '["Tschüss","Hallo","Auf Wiedersehen","Guten Morgen"]'::jsonb, 2, '« Auf Wiedersehen » est la formule polie pour partir ; « Tschüss » est familier, « Guten Morgen » se dit pour saluer le matin.', 2),
    ('146d2576-f2ad-5cba-a0b2-866b39917627'::uuid, 'allemand', '5e', 'Se présenter et saluer', 'Comment dit-on « j’habite à Lyon » ?', 'mcq', '["Ich wohne aus Lyon","Ich komme in Lyon","Ich habe in Lyon","Ich wohne in Lyon"]'::jsonb, 3, 'Le verbe « wohnen » (habiter) se construit avec « in » + la ville. « aus » sert à dire d’où l’on vient (Ich komme aus…).', 3),
    ('b292b20b-412a-58cc-ace2-ef5b52ee9f63'::uuid, 'allemand', '5e', 'Se présenter et saluer', 'Que signifie « vierundsechzig » ?', 'mcq', '["64","46","24","84"]'::jsonb, 0, 'À partir de 21, on dit l’unité d’abord : « vier-und-sechzig » = quatre-et-soixante, soit 64.', 4),
    ('374b1e56-1f40-52af-94d2-79a6dada0541'::uuid, 'allemand', '4e', 'Se présenter et saluer', 'Comment demande-t-on son nom à un professeur, en le vouvoyant ?', 'mcq', '["Wie heißt du ?","Wie heißen Sie ?","Wie heiße Sie ?","Wie bist Sie ?"]'::jsonb, 1, 'Avec « Sie », le verbe prend la terminaison -en : « Wie heißen Sie ? ». « Wie heißt du ? » sert pour tutoyer.', 1),
    ('cd13d394-e6ed-521f-8f1d-247641fd0768'::uuid, 'allemand', '4e', 'Se présenter et saluer', 'Quelle formule utilise-t-on pour dire au revoir poliment à un adulte ?', 'mcq', '["Tschüss","Hallo","Auf Wiedersehen","Guten Morgen"]'::jsonb, 2, '« Auf Wiedersehen » est la formule polie pour partir ; « Tschüss » est familier, « Guten Morgen » se dit pour saluer le matin.', 2),
    ('bbae5ad9-5577-505e-8af3-f9a589dda9c9'::uuid, 'allemand', '4e', 'Se présenter et saluer', 'Comment dit-on « j’habite à Lyon » ?', 'mcq', '["Ich wohne aus Lyon","Ich komme in Lyon","Ich habe in Lyon","Ich wohne in Lyon"]'::jsonb, 3, 'Le verbe « wohnen » (habiter) se construit avec « in » + la ville. « aus » sert à dire d’où l’on vient (Ich komme aus…).', 3),
    ('0b380be6-7d4a-5406-a099-9be97fdafdf5'::uuid, 'allemand', '4e', 'Se présenter et saluer', 'Que signifie « vierundsechzig » ?', 'mcq', '["64","46","24","84"]'::jsonb, 0, 'À partir de 21, on dit l’unité d’abord : « vier-und-sechzig » = quatre-et-soixante, soit 64.', 4),
    ('784e5559-d2ab-57be-baa8-b8e600354ec4'::uuid, 'allemand', '5e', 'Les articles et les trois genres', 'Quel est le genre de « das Mädchen » (la jeune fille) ?', 'mcq', '["Féminin","Masculin","Neutre","Pluriel"]'::jsonb, 2, 'Le genre allemand ne suit pas le français : « das Mädchen » est neutre. C’est pourquoi on apprend chaque nom avec son article.', 1),
    ('9a931518-6b3d-5414-b129-66c9e6ab5aba'::uuid, 'allemand', '5e', 'Les articles et les trois genres', 'Quelle phrase signifie « Le chien voit l’homme » ?', 'mcq', '["Den Hund sieht der Mann","Der Hund sieht den Mann","Der Hund sieht der Mann","Den Hund sieht den Mann"]'::jsonb, 1, 'Le sujet est au nominatif (der Hund), le COD à l’accusatif (den Mann). Dans la première phrase, c’est l’homme qui voit le chien.', 2),
    ('47209fc5-d5af-5709-9e75-1fd9fa197915'::uuid, 'allemand', '5e', 'Les articles et les trois genres', 'Quel article complète « Ich sehe ___ Lampe » (accusatif) ?', 'mcq', '["den","das","dem","die"]'::jsonb, 3, 'Seul le masculin change à l’accusatif. Le féminin garde « die » : « die Lampe » au nominatif comme à l’accusatif.', 3),
    ('d592aee8-0dc4-5cc2-b199-f6ffcf5a1041'::uuid, 'allemand', '5e', 'Les articles et les trois genres', 'Quel article indéfini met-on devant « Buch » (neutre) au nominatif ?', 'mcq', '["ein","eine","einen","der"]'::jsonb, 0, 'Le neutre utilise « ein » : « ein Buch ». « eine » est féminin et « einen » est l’accusatif masculin.', 4),
    ('76637668-8837-5bb3-bbde-824e8fcc32a8'::uuid, 'allemand', '4e', 'Les articles et les trois genres', 'Quel est le genre de « das Mädchen » (la jeune fille) ?', 'mcq', '["Féminin","Masculin","Neutre","Pluriel"]'::jsonb, 2, 'Le genre allemand ne suit pas le français : « das Mädchen » est neutre. C’est pourquoi on apprend chaque nom avec son article.', 1),
    ('e38bf500-4807-5c76-bab4-5728b16d3b1f'::uuid, 'allemand', '4e', 'Les articles et les trois genres', 'Quelle phrase signifie « Le chien voit l’homme » ?', 'mcq', '["Den Hund sieht der Mann","Der Hund sieht den Mann","Der Hund sieht der Mann","Den Hund sieht den Mann"]'::jsonb, 1, 'Le sujet est au nominatif (der Hund), le COD à l’accusatif (den Mann). Dans la première phrase, c’est l’homme qui voit le chien.', 2),
    ('ec6a6529-6b6c-54e9-8a32-a9dbb6e2eae9'::uuid, 'allemand', '4e', 'Les articles et les trois genres', 'Quel article complète « Ich sehe ___ Lampe » (accusatif) ?', 'mcq', '["den","das","dem","die"]'::jsonb, 3, 'Seul le masculin change à l’accusatif. Le féminin garde « die » : « die Lampe » au nominatif comme à l’accusatif.', 3),
    ('9aa1dfba-4d26-5e97-b720-48834741bca9'::uuid, 'allemand', '4e', 'Les articles et les trois genres', 'Quel article indéfini met-on devant « Buch » (neutre) au nominatif ?', 'mcq', '["ein","eine","einen","der"]'::jsonb, 0, 'Le neutre utilise « ein » : « ein Buch ». « eine » est féminin et « einen » est l’accusatif masculin.', 4),
    ('3cd4890b-ec73-59cc-8662-a5061b5055a4'::uuid, 'allemand', '5e', 'Le présent et la place du verbe', 'Quelle phrase est correcte ?', 'mcq', '["Heute ich gehe ins Kino","Heute gehe ich ins Kino","Heute ich ins Kino gehe","Gehe heute ich ins Kino"]'::jsonb, 1, 'Le verbe conjugué reste en deuxième position : « Heute » occupe la première place, le verbe vient ensuite, puis le sujet.', 1),
    ('c614693e-085d-5ea8-93dd-d0f9e194a9a4'::uuid, 'allemand', '5e', 'Le présent et la place du verbe', 'Comment dit-on « vous jouez » (à plusieurs amis) ?', 'mcq', '["ihr spielst","ihr spiele","ihr spielt","ihr spielen"]'::jsonb, 2, 'À la 2e personne du pluriel (ihr), la terminaison est -t : « ihr spielt ». Le -st est réservé à « du ».', 2),
    ('20636f3c-458b-5e3c-a71b-57834e2cd897'::uuid, 'allemand', '5e', 'Le présent et la place du verbe', 'Comment conjugue-t-on « haben » avec « du » ?', 'mcq', '["du habst","du hat","du habt","du hast"]'::jsonb, 3, '« haben » est irrégulier : ich habe, du hast, er hat. Le radical perd son -b- à « du » et « er ».', 3),
    ('e5303e5a-8dae-545c-b446-1547f20e6922'::uuid, 'allemand', '5e', 'Le présent et la place du verbe', 'Que signifie « Warum » ?', 'mcq', '["Pourquoi","Quand","Comment","Qui"]'::jsonb, 0, '« Warum » = pourquoi ; « wann » = quand ; « wie » = comment ; « wer » = qui. Le verbe suit le mot interrogatif.', 4),
    ('95bc4cc0-5ab8-5e48-b900-6774ea976aad'::uuid, 'allemand', '4e', 'Le présent et la place du verbe', 'Quelle phrase est correcte ?', 'mcq', '["Heute ich gehe ins Kino","Heute gehe ich ins Kino","Heute ich ins Kino gehe","Gehe heute ich ins Kino"]'::jsonb, 1, 'Le verbe conjugué reste en deuxième position : « Heute » occupe la première place, le verbe vient ensuite, puis le sujet.', 1),
    ('43b9b7f2-f2fd-5192-891d-ca52ca74cc60'::uuid, 'allemand', '4e', 'Le présent et la place du verbe', 'Comment dit-on « vous jouez » (à plusieurs amis) ?', 'mcq', '["ihr spielst","ihr spiele","ihr spielt","ihr spielen"]'::jsonb, 2, 'À la 2e personne du pluriel (ihr), la terminaison est -t : « ihr spielt ». Le -st est réservé à « du ».', 2),
    ('119b9198-5cbb-5b23-aac2-4c5b759bf9b7'::uuid, 'allemand', '4e', 'Le présent et la place du verbe', 'Comment conjugue-t-on « haben » avec « du » ?', 'mcq', '["du habst","du hat","du habt","du hast"]'::jsonb, 3, '« haben » est irrégulier : ich habe, du hast, er hat. Le radical perd son -b- à « du » et « er ».', 3),
    ('d297027d-e881-5a20-b4e5-46d4da052d85'::uuid, 'allemand', '4e', 'Le présent et la place du verbe', 'Que signifie « Warum » ?', 'mcq', '["Pourquoi","Quand","Comment","Qui"]'::jsonb, 0, '« Warum » = pourquoi ; « wann » = quand ; « wie » = comment ; « wer » = qui. Le verbe suit le mot interrogatif.', 4),
    ('4db0a2a5-28bb-5a49-9bfa-a2b827640390'::uuid, 'anglais', '5e', 'Phrase simple et phrase complexe', 'Quelle phrase est correcte ?', 'mcq', '["I speak well English.","I well speak English.","I speak English well.","I speak English good."]'::jsonb, 2, 'L’adverbe ne se glisse jamais entre le verbe et son complément d’objet : il vient après l’objet, I speak English well.', 1),
    ('0bfb6ead-5c4c-5a6c-9150-7744e3426594'::uuid, 'anglais', '5e', 'Phrase simple et phrase complexe', 'Dans « I think he is right », quel mot a été omis ?', 'mcq', '["which","that","who","what"]'::jsonb, 1, 'He is right est une subordonnée complétive, introduite par that. L’anglais omet très souvent ce that : I think (that) he is right.', 2),
    ('e5d871ed-2ed4-557d-a3b8-3f8fc5a20dc5'::uuid, 'anglais', '5e', 'Phrase simple et phrase complexe', 'Quelle conjonction introduit une condition ?', 'mcq', '["because","while","so that","unless"]'::jsonb, 3, 'Unless (« à moins que, sauf si ») introduit une condition, comme if. Because introduit la cause, while le temps et so that le but.', 3),
    ('7efaa637-9114-5ac6-8354-3c72675df945'::uuid, 'anglais', '5e', 'Phrase simple et phrase complexe', 'Dans « She was tired, so she went to bed », quel procédé relie les deux propositions ?', 'mcq', '["La coordination","La subordination de cause","La subordination relative","La subordination de but"]'::jsonb, 0, 'So relie deux propositions de même rang, qui pourraient chacune tenir seule : c’est la coordination. Ne le confonds pas avec so that, qui introduit un but.', 4),
    ('21adbee1-0cc3-5562-a611-6064f7767a0e'::uuid, 'anglais', '4e', 'Phrase simple et phrase complexe', 'Quelle phrase est correcte ?', 'mcq', '["I speak well English.","I well speak English.","I speak English well.","I speak English good."]'::jsonb, 2, 'L’adverbe ne se glisse jamais entre le verbe et son complément d’objet : il vient après l’objet, I speak English well.', 1),
    ('5695d24a-a553-5aa4-8e6e-9a3a175297f1'::uuid, 'anglais', '4e', 'Phrase simple et phrase complexe', 'Dans « I think he is right », quel mot a été omis ?', 'mcq', '["which","that","who","what"]'::jsonb, 1, 'He is right est une subordonnée complétive, introduite par that. L’anglais omet très souvent ce that : I think (that) he is right.', 2),
    ('12ceb160-ca0c-5ee9-acc8-76e8b1ad1b8a'::uuid, 'anglais', '4e', 'Phrase simple et phrase complexe', 'Quelle conjonction introduit une condition ?', 'mcq', '["because","while","so that","unless"]'::jsonb, 3, 'Unless (« à moins que, sauf si ») introduit une condition, comme if. Because introduit la cause, while le temps et so that le but.', 3),
    ('92895ebd-701c-5659-b3e7-c0573faa30a3'::uuid, 'anglais', '4e', 'Phrase simple et phrase complexe', 'Dans « She was tired, so she went to bed », quel procédé relie les deux propositions ?', 'mcq', '["La coordination","La subordination de cause","La subordination relative","La subordination de but"]'::jsonb, 0, 'So relie deux propositions de même rang, qui pourraient chacune tenir seule : c’est la coordination. Ne le confonds pas avec so that, qui introduit un but.', 4),
    ('d862d216-9dc6-5896-ba6d-abfbe627c7d9'::uuid, 'anglais', '5e', 'Les pronoms personnels', 'This bag isn’t mine. Is it ___?', 'mcq', '["your","yours","you","yourself"]'::jsonb, 1, 'Le pronom possessif remplace tout le groupe (your bag) et s’emploie seul : yours. Your est l’adjectif possessif, toujours suivi d’un nom.', 1),
    ('206a1152-99ab-57c4-80de-d3ffa6a95b88'::uuid, 'anglais', '5e', 'Les pronoms personnels', 'I can’t find my keys. Can you help ___?', 'mcq', '["I","my","mine","me"]'::jsonb, 3, 'Après un verbe ou une préposition, on emploie le pronom complément : me, him, her, us, them. I ne s’emploie que comme sujet.', 2),
    ('c57bab18-9979-5154-bf36-d42dbb4db7c2'::uuid, 'anglais', '5e', 'Les pronoms personnels', 'Comment dit-on « Je l’ai fait moi-même » ?', 'mcq', '["I did it by me.","I did myself it.","I did it myself.","I did it to me."]'::jsonb, 2, 'Le pronom réfléchi sert aussi à insister : I did it myself, placé en fin de phrase.', 3),
    ('3f93c8cc-051e-5ad7-b8e4-1d9e93a3a058'::uuid, 'anglais', '5e', 'Les pronoms personnels', 'Dans « He hurt himself », à quoi sert « himself » ?', 'mcq', '["À dire que l’action revient sur le sujet","À dire qu’il était tout seul","À éviter de répéter un nom","À marquer la possession"]'::jsonb, 0, 'Il s’est fait mal à lui-même : l’action revient sur le sujet, d’où le réfléchi. « Tout seul » se dirait by himself.', 4),
    ('586eb2d6-2cdf-573c-926c-c7ab7bce688b'::uuid, 'anglais', '4e', 'Les pronoms personnels', 'This bag isn’t mine. Is it ___?', 'mcq', '["your","yours","you","yourself"]'::jsonb, 1, 'Le pronom possessif remplace tout le groupe (your bag) et s’emploie seul : yours. Your est l’adjectif possessif, toujours suivi d’un nom.', 1),
