    ('045ec625-2f70-5a09-9063-3f76cf624637'::uuid, 'anglais', '4e', 'Le superlatif', 'Comment dit-on « le moins cher » ?', 'mcq', '["the least expensive","the lesser expensive","the most cheap","the fewest expensive"]'::jsonb, 0, 'Le superlatif d’infériorité se forme avec the least + adjectif, quelle que soit la longueur de l’adjectif.', 3),
    ('43ee26db-690c-590a-886d-e344c6e8242a'::uuid, 'anglais', '4e', 'Le superlatif', 'Quel est le superlatif de « big » ?', 'mcq', '["the bigest","the most big","the biggest","the more big"]'::jsonb, 2, 'Big double sa consonne finale devant -est, comme devant -er : bigger, the biggest.', 4),
    ('34fdc24f-6e80-51a3-a98c-3d55362aeea0'::uuid, 'anglais', '5e', 'Exprimer l’habitude', 'Comment demande-t-on « Habitais-tu ici avant ? » ?', 'mcq', '["Did you used to live here?","Did you use to live here?","Were you use to live here?","Do you used to live here?"]'::jsonb, 1, 'Comme à la négation, used to perd son -d après did : Did you use to live here?', 1),
    ('9ee1c95e-b241-532a-8321-ac89a0e6d604'::uuid, 'anglais', '5e', 'Exprimer l’habitude', 'Quelle phrase est correcte ?', 'mcq', '["She always is late.","She is late always.","Always she is late.","She is always late."]'::jsonb, 3, 'Un adverbe de fréquence se place après be (ou après l’auxiliaire), mais avant le verbe lexical : She is always late, She always plays.', 2),
    ('25b7ea38-8d4a-543e-a2f0-e173b14063aa'::uuid, 'anglais', '5e', 'Exprimer l’habitude', 'Que signifie « I am used to getting up early » ?', 'mcq', '["Je me levais tôt autrefois","Je vais bientôt me lever tôt","J’ai l’habitude de me lever tôt","Je dois me lever tôt"]'::jsonb, 2, 'Be used to + -ING signifie « être habitué à, avoir l’habitude de ». « Je me levais tôt autrefois » se dirait I used to get up early.', 3),
    ('1f25dcb1-5565-5751-9f2a-a42d149d6678'::uuid, 'anglais', '5e', 'Exprimer l’habitude', 'Comment dit-on « Chaque été, nous allions à la plage » ?', 'mcq', '["Every summer, we would go to the beach.","Every summer, we would went to the beach.","Every summer, we were used to go to the beach.","Every summer, we would going to the beach."]'::jsonb, 0, 'Would + base verbale décrit une action répétée dans le passé, comme l’imparfait « nous allions ». Used to go conviendrait aussi.', 4),
    ('2c76925f-e27a-552f-86db-8344574cb616'::uuid, 'anglais', '4e', 'Exprimer l’habitude', 'Comment demande-t-on « Habitais-tu ici avant ? » ?', 'mcq', '["Did you used to live here?","Did you use to live here?","Were you use to live here?","Do you used to live here?"]'::jsonb, 1, 'Comme à la négation, used to perd son -d après did : Did you use to live here?', 1),
    ('84c84fde-a3cc-5a9c-a2dc-5b9a01294925'::uuid, 'anglais', '4e', 'Exprimer l’habitude', 'Quelle phrase est correcte ?', 'mcq', '["She always is late.","She is late always.","Always she is late.","She is always late."]'::jsonb, 3, 'Un adverbe de fréquence se place après be (ou après l’auxiliaire), mais avant le verbe lexical : She is always late, She always plays.', 2),
    ('0b2cc2ff-fd83-59c1-be2d-9e08bd566d05'::uuid, 'anglais', '4e', 'Exprimer l’habitude', 'Que signifie « I am used to getting up early » ?', 'mcq', '["Je me levais tôt autrefois","Je vais bientôt me lever tôt","J’ai l’habitude de me lever tôt","Je dois me lever tôt"]'::jsonb, 2, 'Be used to + -ING signifie « être habitué à, avoir l’habitude de ». « Je me levais tôt autrefois » se dirait I used to get up early.', 3),
    ('cb93a62d-a64c-5776-9f84-2eb06b79079f'::uuid, 'anglais', '4e', 'Exprimer l’habitude', 'Comment dit-on « Chaque été, nous allions à la plage » ?', 'mcq', '["Every summer, we would go to the beach.","Every summer, we would went to the beach.","Every summer, we were used to go to the beach.","Every summer, we would going to the beach."]'::jsonb, 0, 'Would + base verbale décrit une action répétée dans le passé, comme l’imparfait « nous allions ». Used to go conviendrait aussi.', 4),
    ('ad36afd4-094f-5994-8a49-4134380e36b9'::uuid, 'anglais', '5e', 'Exprimer le but', 'Quelle réponse à « Why did you call? » est correcte ?', 'mcq', '["For ask you something.","To ask you something.","For asking you something.","So that ask you something."]'::jsonb, 1, 'Pour répondre à why par un but, on commence souvent par to + base verbale : To ask you something. For + verbe est l’erreur classique.', 1),
    ('5e2ee9a0-3afc-5188-8441-76fec37a0cad'::uuid, 'anglais', '5e', 'Exprimer le but', 'Quelle expression a le même sens que « in order to », dans le même registre formel ?', 'mcq', '["so as to","so that","for","such as"]'::jsonb, 0, 'So as to et in order to expriment le but dans un registre formel, suivis de la base verbale. So that introduit une proposition complète, avec son propre sujet.', 2),
    ('af459ec4-db97-5ee8-b52d-304cbfad0697'::uuid, 'anglais', '5e', 'Exprimer le but', 'She saved money so that her son ___ study abroad.', 'mcq', '["can","to","could","for"]'::jsonb, 2, 'So that est suivi d’une proposition complète, souvent avec un modal ; ici le récit est au passé (saved), d’où could.', 3),
    ('ca96ec8e-8f88-5c00-95b9-480662fe97c9'::uuid, 'anglais', '5e', 'Exprimer le but', 'Que signifie « I went to the shop for bread » ?', 'mcq', '["Je suis allé au magasin grâce au pain","Je suis allé au magasin à cause du pain","Je suis allé au magasin avec du pain","Je suis allé au magasin chercher du pain"]'::jsonb, 3, 'For + nom indique ce qu’on va chercher. Devant un verbe, il faudrait to : I went to the shop to buy bread.', 4),
