    ('e0a3ab09-b33d-570e-82e8-48a8a72be3a1'::uuid, 'anglais', '4e', 'Exprimer le but', 'Quelle expression a le même sens que « in order to », dans le même registre formel ?', 'mcq', '["so as to","so that","for","such as"]'::jsonb, 0, 'So as to et in order to expriment le but dans un registre formel, suivis de la base verbale. So that introduit une proposition complète, avec son propre sujet.', 2),
    ('92ccd5dd-faf9-5422-be39-ef8c733b3b5e'::uuid, 'anglais', '4e', 'Exprimer le but', 'She saved money so that her son ___ study abroad.', 'mcq', '["can","to","could","for"]'::jsonb, 2, 'So that est suivi d’une proposition complète, souvent avec un modal ; ici le récit est au passé (saved), d’où could.', 3),
    ('9f428220-1b4d-5527-ba18-95db145babd4'::uuid, 'anglais', '4e', 'Exprimer le but', 'Que signifie « I went to the shop for bread » ?', 'mcq', '["Je suis allé au magasin grâce au pain","Je suis allé au magasin à cause du pain","Je suis allé au magasin avec du pain","Je suis allé au magasin chercher du pain"]'::jsonb, 3, 'For + nom indique ce qu’on va chercher. Devant un verbe, il faudrait to : I went to the shop to buy bread.', 4),
    ('a8dce29e-e3f3-5c93-a490-ca22443e967a'::uuid, 'anglais', '5e', 'Exprimer la durée', 'Comment traduit-on « Ça fait deux ans que je ne l’ai pas vu » ?', 'mcq', '["It’s two years ago I saw him.","It’s been two years for I saw him.","It’s been two years since I saw him.","It has two years since I saw him."]'::jsonb, 2, 'La tournure it’s been + durée + since + prétérit mesure le temps écoulé depuis un moment du passé.', 1),
    ('45960b75-0dd9-517a-bcb7-93486d379f8c'::uuid, 'anglais', '5e', 'Exprimer la durée', 'It rained a lot ___ the holidays.', 'mcq', '["since","during","ago","while"]'::jsonb, 1, 'During (« pendant ») se place devant un nom : during the holidays. Devant une durée chiffrée, on emploie for : for two hours.', 2),
    ('f8646877-6aa9-537e-8c2e-5528829b5398'::uuid, 'anglais', '5e', 'Exprimer la durée', 'Quelle phrase dit que Tom ne travaille plus là-bas ?', 'mcq', '["Tom worked there for two years.","Tom has worked there for two years.","Tom has worked there since two years.","Tom works there since two years."]'::jsonb, 0, 'For s’emploie à tous les temps : au prétérit (worked), la période est finie ; au present perfect (has worked), elle dure encore.', 3),
    ('48340be9-1ada-533e-b885-19a87c82bd96'::uuid, 'anglais', '5e', 'Exprimer la durée', 'Quel groupe peut suivre « since » ?', 'mcq', '["two hours","a long time","ages","this morning"]'::jsonb, 3, 'Since se construit avec un point de départ (this morning, Monday, 2020). Two hours, a long time et ages sont des durées : elles prennent for.', 4),
    ('7eb9bb92-d927-5548-b3df-2044329fd43e'::uuid, 'anglais', '4e', 'Exprimer la durée', 'Comment traduit-on « Ça fait deux ans que je ne l’ai pas vu » ?', 'mcq', '["It’s two years ago I saw him.","It’s been two years for I saw him.","It’s been two years since I saw him.","It has two years since I saw him."]'::jsonb, 2, 'La tournure it’s been + durée + since + prétérit mesure le temps écoulé depuis un moment du passé.', 1),
    ('48fe83c4-6345-5f5d-9d3f-3a06eb59aa2b'::uuid, 'anglais', '4e', 'Exprimer la durée', 'It rained a lot ___ the holidays.', 'mcq', '["since","during","ago","while"]'::jsonb, 1, 'During (« pendant ») se place devant un nom : during the holidays. Devant une durée chiffrée, on emploie for : for two hours.', 2),
    ('b2ca9649-67b8-529b-9641-187c1d449c2d'::uuid, 'anglais', '4e', 'Exprimer la durée', 'Quelle phrase dit que Tom ne travaille plus là-bas ?', 'mcq', '["Tom worked there for two years.","Tom has worked there for two years.","Tom has worked there since two years.","Tom works there since two years."]'::jsonb, 0, 'For s’emploie à tous les temps : au prétérit (worked), la période est finie ; au present perfect (has worked), elle dure encore.', 3),
    ('72f17634-ecc3-5e15-aef5-c80389160f5a'::uuid, 'anglais', '4e', 'Exprimer la durée', 'Quel groupe peut suivre « since » ?', 'mcq', '["two hours","a long time","ages","this morning"]'::jsonb, 3, 'Since se construit avec un point de départ (this morning, Monday, 2020). Two hours, a long time et ages sont des durées : elles prennent for.', 4),
    ('88403ac9-1dd8-54cd-813f-e47bb8313332'::uuid, 'anglais', '5e', 'Le discours indirect', '« I can’t come tonight. » → She said she ___ come that night.', 'mcq', '["can’t","couldn’t","won’t","didn’t"]'::jsonb, 1, 'Après un verbe introducteur au passé (said), can recule en could, comme will devient would.', 1),
    ('bfbb3803-81cd-5a99-8791-a15ed1f5ce9c'::uuid, 'anglais', '5e', 'Le discours indirect', 'Que devient « tomorrow » au discours indirect ?', 'mcq', '["the day before","yesterday","that day","the next day"]'::jsonb, 3, 'Les repères s’adaptent au moment du récit : tomorrow devient the next day, yesterday the day before, today that day.', 2),
    ('de45d043-8679-5087-8548-57dd30404b38'::uuid, 'anglais', '5e', 'Le discours indirect', 'Comment rapporte-t-on « Don’t be late. » ?', 'mcq', '["She told me not to be late.","She told me don’t be late.","She told me to not late.","She said me not to be late."]'::jsonb, 0, 'Un ordre négatif se rapporte avec tell + complément + not to + base verbale. Say ne prend pas de complément de personne.', 3),
    ('2790eeae-d417-5fde-b7ae-73a0146ee53d'::uuid, 'anglais', '5e', 'Le discours indirect', 'Comment rapporte-t-on « I lost my keys » ?', 'mcq', '["He said he lost my keys.","He said I had lost my keys.","He said he had lost his keys.","He said he has lost his keys."]'::jsonb, 2, 'Les pronoms et les possessifs s’adaptent au nouveau locuteur (I → he, my → his), et le prétérit recule en past perfect.', 4),
    ('91116325-61ab-5073-9b5b-f87d48bc7d48'::uuid, 'anglais', '4e', 'Le discours indirect', '« I can’t come tonight. » → She said she ___ come that night.', 'mcq', '["can’t","couldn’t","won’t","didn’t"]'::jsonb, 1, 'Après un verbe introducteur au passé (said), can recule en could, comme will devient would.', 1),
    ('46e3a3bd-87d8-5832-82f6-a4d64f470f44'::uuid, 'anglais', '4e', 'Le discours indirect', 'Que devient « tomorrow » au discours indirect ?', 'mcq', '["the day before","yesterday","that day","the next day"]'::jsonb, 3, 'Les repères s’adaptent au moment du récit : tomorrow devient the next day, yesterday the day before, today that day.', 2),
    ('a32c0600-c865-5bbc-93a2-44449031da25'::uuid, 'anglais', '4e', 'Le discours indirect', 'Comment rapporte-t-on « Don’t be late. » ?', 'mcq', '["She told me not to be late.","She told me don’t be late.","She told me to not late.","She said me not to be late."]'::jsonb, 0, 'Un ordre négatif se rapporte avec tell + complément + not to + base verbale. Say ne prend pas de complément de personne.', 3),
    ('d39a1dea-4d13-5f1c-a7dc-9eff9d7423bd'::uuid, 'anglais', '4e', 'Le discours indirect', 'Comment rapporte-t-on « I lost my keys » ?', 'mcq', '["He said he lost my keys.","He said I had lost my keys.","He said he had lost his keys.","He said he has lost his keys."]'::jsonb, 2, 'Les pronoms et les possessifs s’adaptent au nouveau locuteur (I → he, my → his), et le prétérit recule en past perfect.', 4),
    ('88c51965-bfcb-5461-be8b-9fcf341a3039'::uuid, 'anglais', '5e', 'Les noms', 'Quel est le pluriel de « watch » ?', 'mcq', '["watchs","watches","watchies","watchen"]'::jsonb, 1, 'Après -s, -sh, -ch ou -x, le pluriel se forme en -es : watches, boxes.', 1),
    ('d8977571-f488-5ab6-9885-272c8d574b3b'::uuid, 'anglais', '5e', 'Les noms', 'Quel est le pluriel de « mouse » ?', 'mcq', '["mouses","mices","mouse","mice"]'::jsonb, 3, 'Mouse fait partie des pluriels irréguliers : mice, sans -s, comme man → men ou foot → feet.', 2),
    ('f9113124-2edf-5f6d-96e1-c056b9d7cc73'::uuid, 'anglais', '5e', 'Les noms', 'Comment écrit-on « les livres des élèves » ?', 'mcq', '["the students’ books","the student’s books","the students’s books","the books’ students"]'::jsonb, 0, 'Quand le possesseur est un pluriel en -s, on ajoute seulement l’apostrophe : the students’ books. The student’s books = les livres d’un seul élève.', 3),
    ('39023f8c-b260-56bc-bd7c-e64880a0c087'::uuid, 'anglais', '5e', 'Les noms', 'Quel est le pluriel de « key » ?', 'mcq', '["kies","keyes","keys","keies"]'::jsonb, 2, 'Le y ne devient -ies qu’après une consonne (city → cities). Après une voyelle, comme dans key ou boy, on ajoute simplement -s.', 4),
    ('d6eca7aa-17c6-5813-8675-ae608039af21'::uuid, 'anglais', '4e', 'Les noms', 'Quel est le pluriel de « watch » ?', 'mcq', '["watchs","watches","watchies","watchen"]'::jsonb, 1, 'Après -s, -sh, -ch ou -x, le pluriel se forme en -es : watches, boxes.', 1),
    ('351a79c7-c466-5e3f-b45b-fa751cc674fd'::uuid, 'anglais', '4e', 'Les noms', 'Quel est le pluriel de « mouse » ?', 'mcq', '["mouses","mices","mouse","mice"]'::jsonb, 3, 'Mouse fait partie des pluriels irréguliers : mice, sans -s, comme man → men ou foot → feet.', 2),
    ('36a131f9-53cd-59f7-a32d-81797cf721e2'::uuid, 'anglais', '4e', 'Les noms', 'Comment écrit-on « les livres des élèves » ?', 'mcq', '["the students’ books","the student’s books","the students’s books","the books’ students"]'::jsonb, 0, 'Quand le possesseur est un pluriel en -s, on ajoute seulement l’apostrophe : the students’ books. The student’s books = les livres d’un seul élève.', 3),
    ('e4431f26-985d-5347-929a-1009493e09ea'::uuid, 'anglais', '4e', 'Les noms', 'Quel est le pluriel de « key » ?', 'mcq', '["kies","keyes","keys","keies"]'::jsonb, 2, 'Le y ne devient -ies qu’après une consonne (city → cities). Après une voyelle, comme dans key ou boy, on ajoute simplement -s.', 4),
    ('920f4731-f956-5248-af48-0e51ad70875e'::uuid, 'anglais', '5e', 'Les articles définis et les articles indéfinis', 'I saw a dog in the park. ___ dog was very big.', 'mcq', '["A","The","An","Some"]'::jsonb, 1, 'Au premier emploi, le chien n’est pas identifié : a dog. Une fois mentionné, il est connu : the dog.', 1),
    ('78d80cc1-4c62-543f-a1bb-44b97c47a472'::uuid, 'anglais', '5e', 'Les articles définis et les articles indéfinis', 'Quelle phrase est correcte ?', 'mcq', '["I have the breakfast at seven.","I have a breakfast at seven.","I have the breakfast at the seven.","I have breakfast at seven."]'::jsonb, 3, 'Les repas s’emploient sans article en anglais : have breakfast, for lunch. Le français dit « le petit déjeuner », l’anglais rien.', 2),
    ('4cc9bf78-72c2-530c-b917-4d5090038b5e'::uuid, 'anglais', '5e', 'Les articles définis et les articles indéfinis', 'Pourquoi dit-on « the sun » ?', 'mcq', '["Parce que le soleil est unique","Parce que sun commence par une consonne","Parce que sun est un nom pluriel","Parce que sun est un nom propre"]'::jsonb, 0, 'Un objet unique est toujours identifié : il prend the, comme the moon.', 3),
    ('2695431a-ed70-5337-b79f-ff05b2f32356'::uuid, 'anglais', '5e', 'Les articles définis et les articles indéfinis', 'Comment traduit-on « Il apprend l’anglais » ?', 'mcq', '["He learns the English.","He learns an English.","He learns English.","He learns the english."]'::jsonb, 2, 'Les langues, comme les pays et les villes, s’emploient sans article, avec une majuscule : English, France, Paris.', 4),
    ('ff87562d-3850-59dd-a1b4-7c154724fb2b'::uuid, 'anglais', '4e', 'Les articles définis et les articles indéfinis', 'I saw a dog in the park. ___ dog was very big.', 'mcq', '["A","The","An","Some"]'::jsonb, 1, 'Au premier emploi, le chien n’est pas identifié : a dog. Une fois mentionné, il est connu : the dog.', 1),
    ('5ab15493-716c-53c4-9717-3947a92efb1e'::uuid, 'anglais', '4e', 'Les articles définis et les articles indéfinis', 'Quelle phrase est correcte ?', 'mcq', '["I have the breakfast at seven.","I have a breakfast at seven.","I have the breakfast at the seven.","I have breakfast at seven."]'::jsonb, 3, 'Les repas s’emploient sans article en anglais : have breakfast, for lunch. Le français dit « le petit déjeuner », l’anglais rien.', 2),
    ('03c1165f-6543-5d80-8c8c-42a943c67c50'::uuid, 'anglais', '4e', 'Les articles définis et les articles indéfinis', 'Pourquoi dit-on « the sun » ?', 'mcq', '["Parce que le soleil est unique","Parce que sun commence par une consonne","Parce que sun est un nom pluriel","Parce que sun est un nom propre"]'::jsonb, 0, 'Un objet unique est toujours identifié : il prend the, comme the moon.', 3),
    ('6f0be8d9-31cf-5459-8f62-7ee730ab82fd'::uuid, 'anglais', '4e', 'Les articles définis et les articles indéfinis', 'Comment traduit-on « Il apprend l’anglais » ?', 'mcq', '["He learns the English.","He learns an English.","He learns English.","He learns the english."]'::jsonb, 2, 'Les langues, comme les pays et les villes, s’emploient sans article, avec une majuscule : English, France, Paris.', 4),
    ('082131b5-b78f-5b62-97ac-f238b82ca627'::uuid, 'anglais', '5e', 'Les adjectifs démonstratifs', 'Qu’entend-on de différent entre « this » et « these » ?', 'mcq', '["La consonne du début","La longueur de la voyelle","Le s final, qui est muet","L’accent tonique du mot"]'::jsonb, 1, 'This se prononce avec un [ɪ] court, these avec un [iː] long : c’est la seule différence audible entre le singulier et le pluriel.', 1),
    ('ff872c07-e9b3-5246-9a88-fb46f2236855'::uuid, 'anglais', '5e', 'Les adjectifs démonstratifs', 'Look at ___ birds up there in the sky!', 'mcq', '["this","these","that","those"]'::jsonb, 3, 'Les oiseaux sont loin (up there) et ils sont plusieurs : pluriel + éloigné = those.', 2),
    ('428da826-9f4c-5b41-a5f5-0770c8d03988'::uuid, 'anglais', '5e', 'Les adjectifs démonstratifs', 'Dans « That was strange! », que reprend « that » ?', 'mcq', '["Un fait qui vient de se passer","Un objet que l’on tient","Une personne toute proche","Un moment qui va arriver"]'::jsonb, 0, 'That renvoie au passé ou à ce qui s’éloigne : ici, ce qui vient d’arriver. This renvoie plutôt au présent ou au futur proche.', 3),
    ('c9dfa7d4-11dc-5ac7-98f4-09ec6e004146'::uuid, 'anglais', '5e', 'Les adjectifs démonstratifs', 'En anglais, le démonstratif change selon que le nom est masculin ou féminin.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les démonstratifs ne varient qu’en nombre et en distance : this boy et this girl, these boys et these girls.', 4),
    ('4b4ddc7f-dcdd-5381-b9f6-c34ae47f4e09'::uuid, 'anglais', '4e', 'Les adjectifs démonstratifs', 'Qu’entend-on de différent entre « this » et « these » ?', 'mcq', '["La consonne du début","La longueur de la voyelle","Le s final, qui est muet","L’accent tonique du mot"]'::jsonb, 1, 'This se prononce avec un [ɪ] court, these avec un [iː] long : c’est la seule différence audible entre le singulier et le pluriel.', 1),
    ('198033a5-f73d-5eb3-8519-1009ae697e48'::uuid, 'anglais', '4e', 'Les adjectifs démonstratifs', 'Look at ___ birds up there in the sky!', 'mcq', '["this","these","that","those"]'::jsonb, 3, 'Les oiseaux sont loin (up there) et ils sont plusieurs : pluriel + éloigné = those.', 2),
    ('217a2476-bea6-582b-8a49-c9f13bee30cd'::uuid, 'anglais', '4e', 'Les adjectifs démonstratifs', 'Dans « That was strange! », que reprend « that » ?', 'mcq', '["Un fait qui vient de se passer","Un objet que l’on tient","Une personne toute proche","Un moment qui va arriver"]'::jsonb, 0, 'That renvoie au passé ou à ce qui s’éloigne : ici, ce qui vient d’arriver. This renvoie plutôt au présent ou au futur proche.', 3),
    ('abead5ec-232a-59ce-8a93-98c44ea08dbc'::uuid, 'anglais', '4e', 'Les adjectifs démonstratifs', 'En anglais, le démonstratif change selon que le nom est masculin ou féminin.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les démonstratifs ne varient qu’en nombre et en distance : this boy et this girl, these boys et these girls.', 4),
    ('31a7d55c-f156-5aac-ae54-b7ce6ee7ffd4'::uuid, 'anglais', '5e', 'Exprimer la possession', '___ bag is this? — It’s Kate’s.', 'mcq', '["Who","Whose","Whom","Who’s"]'::jsonb, 1, 'Whose interroge sur le possesseur : « À qui est ce sac ? ». Who’s est la contraction de who is.', 1),
    ('21f1f413-ad8e-57a0-b1c5-51c28d67e58c'::uuid, 'anglais', '5e', 'Exprimer la possession', 'Comment traduit-on « le journal d’aujourd’hui » ?', 'mcq', '["the newspaper of today","today newspaper","today’s newspaper","the today’s newspaper"]'::jsonb, 2, 'Le génitif en ’s s’emploie aussi avec les expressions de temps : today’s newspaper, a week’s holiday.', 2),
    ('5787ea29-96ec-59c7-9385-ee6811abb4d8'::uuid, 'anglais', '5e', 'Exprimer la possession', 'This isn’t my pen. It’s ___.', 'mcq', '["her","her’s","she’s","hers"]'::jsonb, 3, 'Le pronom possessif remplace tout le groupe (her pen) : hers, sans apostrophe et sans nom derrière.', 3),
    ('7c29a5c3-c233-597b-985b-d06d4eb1d218'::uuid, 'anglais', '5e', 'Exprimer la possession', 'The Smiths love ___ new house.', 'mcq', '["their","theirs","them","they"]'::jsonb, 0, 'Devant un nom, on emploie l’adjectif possessif : their house. Theirs est le pronom, employé seul : The house is theirs.', 4),
    ('0b9105a3-294f-5cf1-a355-a1a144f39182'::uuid, 'anglais', '4e', 'Exprimer la possession', '___ bag is this? — It’s Kate’s.', 'mcq', '["Who","Whose","Whom","Who’s"]'::jsonb, 1, 'Whose interroge sur le possesseur : « À qui est ce sac ? ». Who’s est la contraction de who is.', 1),
    ('89f00e35-9e90-503b-9122-d5dbe9ba4dcf'::uuid, 'anglais', '4e', 'Exprimer la possession', 'Comment traduit-on « le journal d’aujourd’hui » ?', 'mcq', '["the newspaper of today","today newspaper","today’s newspaper","the today’s newspaper"]'::jsonb, 2, 'Le génitif en ’s s’emploie aussi avec les expressions de temps : today’s newspaper, a week’s holiday.', 2),
    ('35418ed5-5b38-597d-837a-d115ee6d0876'::uuid, 'anglais', '4e', 'Exprimer la possession', 'This isn’t my pen. It’s ___.', 'mcq', '["her","her’s","she’s","hers"]'::jsonb, 3, 'Le pronom possessif remplace tout le groupe (her pen) : hers, sans apostrophe et sans nom derrière.', 3),
    ('71076496-4ea9-5e22-be60-6178353f7e64'::uuid, 'anglais', '4e', 'Exprimer la possession', 'The Smiths love ___ new house.', 'mcq', '["their","theirs","them","they"]'::jsonb, 0, 'Devant un nom, on emploie l’adjectif possessif : their house. Theirs est le pronom, employé seul : The house is theirs.', 4),
    ('e3eb1ed5-3e52-54d3-8965-97c52fa67c29'::uuid, 'anglais', '5e', 'Exprimer une quantité', 'There is ___ milk in the fridge. We must buy some.', 'mcq', '["no","any","many","a few"]'::jsonb, 0, 'No signifie « pas de » et équivaut à not any : There is no milk = There isn’t any milk.', 1),
    ('75857a4a-99b0-54da-b87f-186671afacd2'::uuid, 'anglais', '5e', 'Exprimer une quantité', 'Quelle phrase est correcte ?', 'mcq', '["She doesn’t run enough fast.","She doesn’t run enough of fast.","She doesn’t enough run fast.","She doesn’t run fast enough."]'::jsonb, 3, 'Enough se place après un adjectif ou un adverbe (fast enough), mais devant un nom (enough money).', 2),
    ('0b2e70fa-bcb6-5798-aba2-e4d045f34205'::uuid, 'anglais', '5e', 'Exprimer une quantité', 'There are too ___ people in this room.', 'mcq', '["much","many","lot","little"]'::jsonb, 1, 'People est un pluriel dénombrable : « trop de » se dit too many. Too much s’emploie avec un indénombrable.', 3),
    ('0cef3927-71fb-51ef-a00b-65f6ce86eafa'::uuid, 'anglais', '5e', 'Exprimer une quantité', '___ student has a locker at school.', 'mcq', '["All","Both","Every","Many"]'::jsonb, 2, 'Every est suivi d’un nom singulier : every student, et le verbe est au singulier (has). All, both et many demandent un pluriel.', 4),
    ('32ad8972-05fc-5986-b841-baed83e49e18'::uuid, 'anglais', '4e', 'Exprimer une quantité', 'There is ___ milk in the fridge. We must buy some.', 'mcq', '["no","any","many","a few"]'::jsonb, 0, 'No signifie « pas de » et équivaut à not any : There is no milk = There isn’t any milk.', 1),
    ('609c905e-8c51-5429-862e-46bb532cd1b6'::uuid, 'anglais', '4e', 'Exprimer une quantité', 'Quelle phrase est correcte ?', 'mcq', '["She doesn’t run enough fast.","She doesn’t run enough of fast.","She doesn’t enough run fast.","She doesn’t run fast enough."]'::jsonb, 3, 'Enough se place après un adjectif ou un adverbe (fast enough), mais devant un nom (enough money).', 2),
    ('4c6276e9-0a75-5a83-8b8b-d229eaefebb7'::uuid, 'anglais', '4e', 'Exprimer une quantité', 'There are too ___ people in this room.', 'mcq', '["much","many","lot","little"]'::jsonb, 1, 'People est un pluriel dénombrable : « trop de » se dit too many. Too much s’emploie avec un indénombrable.', 3),
    ('d62791bd-dec3-520e-9df7-7db31dc78e45'::uuid, 'anglais', '4e', 'Exprimer une quantité', '___ student has a locker at school.', 'mcq', '["All","Both","Every","Many"]'::jsonb, 2, 'Every est suivi d’un nom singulier : every student, et le verbe est au singulier (has). All, both et many demandent un pluriel.', 4),
    ('5d85b927-0625-5473-9718-a38666d65e6f'::uuid, 'anglais', '5e', 'Les adjectifs qualificatifs', 'Que signifie « The dog was frightened » ?', 'mcq', '["Le chien faisait peur","Le chien était surprenant","Le chien avait peur","Le chien était fatigant"]'::jsonb, 2, 'La terminaison -ed décrit ce que ressent le sujet : frightened = effrayé. Un chien qui fait peur serait frightening.', 1),
    ('41324b77-0144-58ad-8e3c-486f987e35db'::uuid, 'anglais', '5e', 'Les adjectifs qualificatifs', 'The trip was long and ___. I need to sleep!', 'mcq', '["tired","tiring","tire","tiredly"]'::jsonb, 1, 'Le voyage provoque la fatigue : tiring (fatigant). Tired (fatigué) décrit ce que ressent une personne : I am tired.', 2),
    ('a2796f3e-b2f5-5cb7-85bc-ac00a9a806e2'::uuid, 'anglais', '5e', 'Les adjectifs qualificatifs', 'Que désigne « the young » ?', 'mcq', '["Le jeune homme","La jeunesse d’une personne","Le plus jeune de la famille","Les jeunes, en général"]'::jsonb, 3, 'Précédé de the, certains adjectifs désignent tout un groupe de personnes : the young = les jeunes, avec un verbe au pluriel.', 3),
    ('8b68a6cc-ac31-5848-aee4-f790a6d6b302'::uuid, 'anglais', '5e', 'Les adjectifs qualificatifs', 'Quel groupe respecte l’ordre des adjectifs ?', 'mcq', '["an old French wooden table","a French old wooden table","a wooden old French table","an old wooden French table"]'::jsonb, 0, 'L’ordre va de l’âge (old) à l’origine (French) puis à la matière (wooden), juste avant le nom.', 4),
    ('6a4b83ff-86b4-5086-aeb1-cba5e8c44253'::uuid, 'anglais', '4e', 'Les adjectifs qualificatifs', 'Que signifie « The dog was frightened » ?', 'mcq', '["Le chien faisait peur","Le chien était surprenant","Le chien avait peur","Le chien était fatigant"]'::jsonb, 2, 'La terminaison -ed décrit ce que ressent le sujet : frightened = effrayé. Un chien qui fait peur serait frightening.', 1),
    ('06223de7-7a5a-5feb-a8b7-252ee9cc1ec3'::uuid, 'anglais', '4e', 'Les adjectifs qualificatifs', 'The trip was long and ___. I need to sleep!', 'mcq', '["tired","tiring","tire","tiredly"]'::jsonb, 1, 'Le voyage provoque la fatigue : tiring (fatigant). Tired (fatigué) décrit ce que ressent une personne : I am tired.', 2),
    ('21dfdc8d-f98b-5282-acc0-461e76b66ca2'::uuid, 'anglais', '4e', 'Les adjectifs qualificatifs', 'Que désigne « the young » ?', 'mcq', '["Le jeune homme","La jeunesse d’une personne","Le plus jeune de la famille","Les jeunes, en général"]'::jsonb, 3, 'Précédé de the, certains adjectifs désignent tout un groupe de personnes : the young = les jeunes, avec un verbe au pluriel.', 3),
    ('2adc0a5b-28c1-5c2e-887b-fb691180b95a'::uuid, 'anglais', '4e', 'Les adjectifs qualificatifs', 'Quel groupe respecte l’ordre des adjectifs ?', 'mcq', '["an old French wooden table","a French old wooden table","a wooden old French table","an old wooden French table"]'::jsonb, 0, 'L’ordre va de l’âge (old) à l’origine (French) puis à la matière (wooden), juste avant le nom.', 4),
    ('900a5fa0-153c-5f1e-977b-238a4627606a'::uuid, 'anglais', '5e', 'Les verbes lexicaux et les auxiliaires', 'Quelle phrase est correcte ?', 'mcq', '["She cans swim.","She can swims.","She can swim.","She does can swim."]'::jsonb, 2, 'Les modaux sont invariables : pas de -s à la 3e personne, et le verbe qui suit reste à la base verbale.', 1),
    ('b60bb42e-54e9-5a84-a728-b741e9b2e474'::uuid, 'anglais', '5e', 'Les verbes lexicaux et les auxiliaires', 'Quelle est la forme négative de « He plays tennis » ?', 'mcq', '["He doesn’t play tennis.","He doesn’t plays tennis.","He not plays tennis.","He plays not tennis."]'::jsonb, 0, 'Au présent simple, la négation passe par does + not ; le -s est porté par l’auxiliaire, et play revient à la base verbale.', 2),
    ('b9137394-4b77-5616-b28f-34c0f3defb40'::uuid, 'anglais', '5e', 'Les verbes lexicaux et les auxiliaires', 'Comment pose-t-on la question à partir de « She is French » ?', 'mcq', '["Does she be French?","Is she French?","Does she is French?","Is French she?"]'::jsonb, 1, 'Même quand il est le verbe principal, be garde ses pouvoirs d’auxiliaire : il passe lui-même devant le sujet, sans do.', 3),
    ('aad937d4-dc5e-5d8d-a05f-0d58ae405c5c'::uuid, 'anglais', '5e', 'Les verbes lexicaux et les auxiliaires', 'Lequel de ces verbes est un verbe lexical ?', 'mcq', '["can","must","should","think"]'::jsonb, 3, 'Un verbe lexical porte le sens de l’action (think, work, eat). Can, must et should sont des modaux, qui construisent la phrase.', 4),
    ('650d8098-a573-50d9-ad50-af23739af33a'::uuid, 'anglais', '4e', 'Les verbes lexicaux et les auxiliaires', 'Quelle phrase est correcte ?', 'mcq', '["She cans swim.","She can swims.","She can swim.","She does can swim."]'::jsonb, 2, 'Les modaux sont invariables : pas de -s à la 3e personne, et le verbe qui suit reste à la base verbale.', 1),
    ('94b4a0c7-f5b7-53cd-81fe-5e208e71b200'::uuid, 'anglais', '4e', 'Les verbes lexicaux et les auxiliaires', 'Quelle est la forme négative de « He plays tennis » ?', 'mcq', '["He doesn’t play tennis.","He doesn’t plays tennis.","He not plays tennis.","He plays not tennis."]'::jsonb, 0, 'Au présent simple, la négation passe par does + not ; le -s est porté par l’auxiliaire, et play revient à la base verbale.', 2),
    ('380052a2-7f74-55b7-a941-9fb1cfc9a2d1'::uuid, 'anglais', '4e', 'Les verbes lexicaux et les auxiliaires', 'Comment pose-t-on la question à partir de « She is French » ?', 'mcq', '["Does she be French?","Is she French?","Does she is French?","Is French she?"]'::jsonb, 1, 'Même quand il est le verbe principal, be garde ses pouvoirs d’auxiliaire : il passe lui-même devant le sujet, sans do.', 3),
    ('1bba9c35-36e9-563c-8ebb-bbebf03d0dbc'::uuid, 'anglais', '4e', 'Les verbes lexicaux et les auxiliaires', 'Lequel de ces verbes est un verbe lexical ?', 'mcq', '["can","must","should","think"]'::jsonb, 3, 'Un verbe lexical porte le sens de l’action (think, work, eat). Can, must et should sont des modaux, qui construisent la phrase.', 4),
    ('2e9f0943-774b-5bdc-9488-2ed3357d03ca'::uuid, 'anglais', '5e', 'Les auxiliaires BE et HAVE', 'Comment dit-on « J’ai froid » en anglais ?', 'mcq', '["I have cold.","I am cold.","I have a cold feeling.","I am having cold."]'::jsonb, 1, 'Pour le froid, la faim, la soif, on emploie BE : I am cold, I am hungry. « I have a cold » signifie « j’ai un rhume ».', 1),
    ('bf8a0fa6-aa75-504f-a5a9-6edd07cfd85f'::uuid, 'anglais', '5e', 'Les auxiliaires BE et HAVE', 'Que représente la contraction « he’s » dans « He’s finished his homework » ?', 'mcq', '["he is","he was","he has","he does"]'::jsonb, 2, 'C’est ce qui suit qui tranche : après « finished » (un participe passé), « he’s » vaut « he has ». Dans « he’s tired », ce serait « he is ».', 2),
    ('ef2e1b4b-ac28-5b15-972b-b42048068f53'::uuid, 'anglais', '5e', 'Les auxiliaires BE et HAVE', 'Comment interroge-t-on « She has breakfast at eight » (have d’action) ?', 'mcq', '["Has she breakfast at eight?","Does she has breakfast at eight?","Have she breakfast at eight?","Does she have breakfast at eight?"]'::jsonb, 3, 'Dans une expression d’action (have breakfast, have a shower), have se comporte comme un verbe ordinaire : on utilise do, puis la base verbale.', 3),
    ('6e75e872-b4bf-5c0b-adda-e85e789ab4a0'::uuid, 'anglais', '5e', 'Les auxiliaires BE et HAVE', 'Quel est le prétérit de « have » à la troisième personne du singulier ?', 'mcq', '["had","has","haved","have had"]'::jsonb, 0, 'Au prétérit, have donne « had » pour toutes les personnes, sans -s : she had, they had.', 4),
    ('eb4e5f1d-9db0-5052-a666-1a02ecdaab55'::uuid, 'anglais', '4e', 'Les auxiliaires BE et HAVE', 'Comment dit-on « J’ai froid » en anglais ?', 'mcq', '["I have cold.","I am cold.","I have a cold feeling.","I am having cold."]'::jsonb, 1, 'Pour le froid, la faim, la soif, on emploie BE : I am cold, I am hungry. « I have a cold » signifie « j’ai un rhume ».', 1),
    ('2f5903d4-e8f7-51eb-8fcc-f1f18a7a612c'::uuid, 'anglais', '4e', 'Les auxiliaires BE et HAVE', 'Que représente la contraction « he’s » dans « He’s finished his homework » ?', 'mcq', '["he is","he was","he has","he does"]'::jsonb, 2, 'C’est ce qui suit qui tranche : après « finished » (un participe passé), « he’s » vaut « he has ». Dans « he’s tired », ce serait « he is ».', 2),
    ('91280d8f-467b-586a-9b44-77ee0a143ffb'::uuid, 'anglais', '4e', 'Les auxiliaires BE et HAVE', 'Comment interroge-t-on « She has breakfast at eight » (have d’action) ?', 'mcq', '["Has she breakfast at eight?","Does she has breakfast at eight?","Have she breakfast at eight?","Does she have breakfast at eight?"]'::jsonb, 3, 'Dans une expression d’action (have breakfast, have a shower), have se comporte comme un verbe ordinaire : on utilise do, puis la base verbale.', 3),
    ('0c8ae4fb-eab0-5274-a0bd-7d15b2e13458'::uuid, 'anglais', '4e', 'Les auxiliaires BE et HAVE', 'Quel est le prétérit de « have » à la troisième personne du singulier ?', 'mcq', '["had","has","haved","have had"]'::jsonb, 0, 'Au prétérit, have donne « had » pour toutes les personnes, sans -s : she had, they had.', 4),
    ('6d2eb98e-5fc2-59b2-9c44-8fa122b7a32b'::uuid, 'anglais', '5e', 'L’auxiliaire DO', 'Quelle phrase exprime correctement l’insistance au passé ?', 'mcq', '["I did liked it!","I did like it!","I do liked it!","I did likes it!"]'::jsonb, 1, 'L’insistance se marque avec did accentué suivi de la base verbale : I did like it! Le passé est porté par did seulement.', 1),
    ('b143313f-e3f9-5059-aa12-5760d69a3766'::uuid, 'anglais', '5e', 'L’auxiliaire DO', 'Comment demande-t-on « Qu’est-ce que tu fais dans la vie ? »', 'mcq', '["What you do?","What are you do?","What do you do?","What does you do?"]'::jsonb, 2, 'Ici « do » est à la fois auxiliaire (premier do) et verbe lexical (second do) : What do you do?', 2),
    ('8064b7aa-bdab-5673-a4b6-26902df42b6b'::uuid, 'anglais', '5e', 'L’auxiliaire DO', 'Quelle phrase est correcte ?', 'mcq', '["Can he swim?","Does he can swim?","Do he can swim?","Does he swim can?"]'::jsonb, 0, 'Avec un modal comme can, on n’emploie jamais do : on inverse simplement le modal et le sujet.', 3),
    ('3ddfb191-5a6b-5ace-81c6-0a2a4c41a62b'::uuid, 'anglais', '5e', 'L’auxiliaire DO', 'Dans « Does she work here? », pourquoi « work » n’a-t-il pas de -s ?', 'mcq', '["Parce que work est un verbe irrégulier","Parce que does porte déjà la marque de la 3e personne","Parce qu’une question supprime toujours le -s","Parce qu’on parle au passé"]'::jsonb, 1, 'Une phrase ne porte qu’une seule marque de temps et de personne : elle est sur does, donc le verbe lexical revient à la base verbale.', 4),
    ('739c8794-a004-5bf8-8740-a5b8c4995639'::uuid, 'anglais', '4e', 'L’auxiliaire DO', 'Quelle phrase exprime correctement l’insistance au passé ?', 'mcq', '["I did liked it!","I did like it!","I do liked it!","I did likes it!"]'::jsonb, 1, 'L’insistance se marque avec did accentué suivi de la base verbale : I did like it! Le passé est porté par did seulement.', 1),
    ('c9016d68-3a6f-5b13-b6b2-03b382c94b62'::uuid, 'anglais', '4e', 'L’auxiliaire DO', 'Comment demande-t-on « Qu’est-ce que tu fais dans la vie ? »', 'mcq', '["What you do?","What are you do?","What do you do?","What does you do?"]'::jsonb, 2, 'Ici « do » est à la fois auxiliaire (premier do) et verbe lexical (second do) : What do you do?', 2),
    ('48032d83-3a99-55db-bf4e-574d041f33c8'::uuid, 'anglais', '4e', 'L’auxiliaire DO', 'Quelle phrase est correcte ?', 'mcq', '["Can he swim?","Does he can swim?","Do he can swim?","Does he swim can?"]'::jsonb, 0, 'Avec un modal comme can, on n’emploie jamais do : on inverse simplement le modal et le sujet.', 3),
    ('02100da9-5cb8-56c3-89ac-acc184d34e77'::uuid, 'anglais', '4e', 'L’auxiliaire DO', 'Dans « Does she work here? », pourquoi « work » n’a-t-il pas de -s ?', 'mcq', '["Parce que work est un verbe irrégulier","Parce que does porte déjà la marque de la 3e personne","Parce qu’une question supprime toujours le -s","Parce qu’on parle au passé"]'::jsonb, 1, 'Une phrase ne porte qu’une seule marque de temps et de personne : elle est sur does, donc le verbe lexical revient à la base verbale.', 4),
    ('408e275a-98dd-516e-af0b-421b5a7af076'::uuid, 'anglais', '5e', 'Expression de la modalité : l’obligation', 'Comment dit-on « Tu devras partir demain » ?', 'mcq', '["You must will go tomorrow.","You will have to go tomorrow.","You will must go tomorrow.","You have to will go tomorrow."]'::jsonb, 1, 'Must n’a pas de futur : on le remplace par will have to. On n’empile jamais deux modaux.', 1),
    ('2482f393-8403-5023-86ba-8591f43a57ac'::uuid, 'anglais', '5e', 'Expression de la modalité : l’obligation', 'Que signifie « You needn’t worry » ?', 'mcq', '["Ce n’est pas nécessaire de t’inquiéter","Il t’est interdit de t’inquiéter","Tu devrais t’inquiéter","Tu n’as pas pu t’inquiéter"]'::jsonb, 0, 'Needn’t a le même sens que don’t have to : absence d’obligation, et non interdiction.', 2),
    ('e791c26c-832c-5998-815a-c4b5097d1a4e'::uuid, 'anglais', '5e', 'Expression de la modalité : l’obligation', 'Quelle est la négation correcte de « He has to go » ?', 'mcq', '["He hasn’t to go.","He doesn’t has to go.","He doesn’t have to go.","He mustn’t have to go."]'::jsonb, 2, 'Have to se nie avec do : he doesn’t have to go. Après doesn’t, have revient à la base verbale.', 3),
    ('a9cccbd5-36c6-55e7-b41c-b9826a014da4'::uuid, 'anglais', '5e', 'Expression de la modalité : l’obligation', 'Comment dit-on « Il n’était pas autorisé à entrer » ?', 'mcq', '["He mustn’t enter.","He musted not enter.","He must not entered.","He wasn’t allowed to enter."]'::jsonb, 3, 'Au passé, l’interdiction se dit couldn’t ou wasn’t allowed to. Must n’a pas de forme passée.', 4),
    ('6e9b20ef-e177-5342-b335-35ab380962dd'::uuid, 'anglais', '4e', 'Expression de la modalité : l’obligation', 'Comment dit-on « Tu devras partir demain » ?', 'mcq', '["You must will go tomorrow.","You will have to go tomorrow.","You will must go tomorrow.","You have to will go tomorrow."]'::jsonb, 1, 'Must n’a pas de futur : on le remplace par will have to. On n’empile jamais deux modaux.', 1),
    ('cc3fb8fd-0be2-5771-a96f-6bf6d86ac952'::uuid, 'anglais', '4e', 'Expression de la modalité : l’obligation', 'Que signifie « You needn’t worry » ?', 'mcq', '["Ce n’est pas nécessaire de t’inquiéter","Il t’est interdit de t’inquiéter","Tu devrais t’inquiéter","Tu n’as pas pu t’inquiéter"]'::jsonb, 0, 'Needn’t a le même sens que don’t have to : absence d’obligation, et non interdiction.', 2),
    ('a9cb851d-b206-59c7-b870-7ce8c8b6906d'::uuid, 'anglais', '4e', 'Expression de la modalité : l’obligation', 'Quelle est la négation correcte de « He has to go » ?', 'mcq', '["He hasn’t to go.","He doesn’t has to go.","He doesn’t have to go.","He mustn’t have to go."]'::jsonb, 2, 'Have to se nie avec do : he doesn’t have to go. Après doesn’t, have revient à la base verbale.', 3),
    ('b1b139a7-568b-5912-9061-f504d8432a1b'::uuid, 'anglais', '4e', 'Expression de la modalité : l’obligation', 'Comment dit-on « Il n’était pas autorisé à entrer » ?', 'mcq', '["He mustn’t enter.","He musted not enter.","He must not entered.","He wasn’t allowed to enter."]'::jsonb, 3, 'Au passé, l’interdiction se dit couldn’t ou wasn’t allowed to. Must n’a pas de forme passée.', 4),
    ('0c752676-d693-5f61-8708-7e0ce51bf7b9'::uuid, 'anglais', '5e', 'Expression de la modalité : la capacité', 'Comment dit-on « J’ai réussi à finir » avec le present perfect ?', 'mcq', '["I have could finish.","I have been able to finish.","I have can finish.","I have able to finish."]'::jsonb, 1, 'Can n’a pas de participe passé : au present perfect, on utilise be able to, ici have been able to.', 1),
    ('a84b9cf7-8dde-547e-8702-4b125bf24f58'::uuid, 'anglais', '5e', 'Expression de la modalité : la capacité', 'Quelle phrase est une négation correcte de la capacité ?', 'mcq', '["I cannot swim.","I don’t can swim.","I can not to swim.","I cans not swim."]'::jsonb, 0, 'La négation de can est can’t ou cannot (en un seul mot). Pas de do, pas de « to ».', 2),
    ('6b68fed8-2182-5b45-8f3e-2080630c07b8'::uuid, 'anglais', '5e', 'Expression de la modalité : la capacité', 'Quel verbe de perception s’emploie souvent avec can, alors que le français dit simplement « j’entends » ?', 'mcq', '["hope","want","hear","need"]'::jsonb, 2, 'Avec see, hear, feel, smell, taste, l’anglais ajoute can : I can hear music.', 3),
    ('5de3b688-a918-50b8-aa1c-1a04648b069d'::uuid, 'anglais', '5e', 'Expression de la modalité : la capacité', 'Comment exprime-t-on la capacité après « might » ?', 'mcq', '["You might can come.","You might could come.","You might able to come.","You might be able to come."]'::jsonb, 3, 'Can ne s’emploie pas après un autre modal : on prend be able to. Ici : You might be able to come.', 4),
    ('bc228384-3840-5ba6-b2c9-9f345d7bf4a8'::uuid, 'anglais', '4e', 'Expression de la modalité : la capacité', 'Comment dit-on « J’ai réussi à finir » avec le present perfect ?', 'mcq', '["I have could finish.","I have been able to finish.","I have can finish.","I have able to finish."]'::jsonb, 1, 'Can n’a pas de participe passé : au present perfect, on utilise be able to, ici have been able to.', 1),
    ('b4140ce4-4938-5efd-a214-2ef1fb33770f'::uuid, 'anglais', '4e', 'Expression de la modalité : la capacité', 'Quelle phrase est une négation correcte de la capacité ?', 'mcq', '["I cannot swim.","I don’t can swim.","I can not to swim.","I cans not swim."]'::jsonb, 0, 'La négation de can est can’t ou cannot (en un seul mot). Pas de do, pas de « to ».', 2),
    ('cc204cf1-99b2-5dba-a8c9-22c191a1da7e'::uuid, 'anglais', '4e', 'Expression de la modalité : la capacité', 'Quel verbe de perception s’emploie souvent avec can, alors que le français dit simplement « j’entends » ?', 'mcq', '["hope","want","hear","need"]'::jsonb, 2, 'Avec see, hear, feel, smell, taste, l’anglais ajoute can : I can hear music.', 3),
    ('0ee7846f-78d2-5d5b-a241-a205332a9f63'::uuid, 'anglais', '4e', 'Expression de la modalité : la capacité', 'Comment exprime-t-on la capacité après « might » ?', 'mcq', '["You might can come.","You might could come.","You might able to come.","You might be able to come."]'::jsonb, 3, 'Can ne s’emploie pas après un autre modal : on prend be able to. Ici : You might be able to come.', 4),
    ('5f4dc6be-a959-586c-aad1-6b5db96cf6a0'::uuid, 'anglais', '5e', 'Expression de la modalité : la permission', 'Que signifie « You could go » ?', 'mcq', '["Tu as la permission d’y aller","Tu pourrais y aller : c’est une suggestion","Tu dois y aller","Tu y es allé"]'::jsonb, 1, 'Could sert à demander une permission, mais pas à l’accorder : « You could go » est une suggestion.', 1),
    ('32aa2c5a-6857-5acb-aeac-194dc31f8cc6'::uuid, 'anglais', '5e', 'Expression de la modalité : la permission', 'Comment dit-on « Tu auras le droit de voter à 18 ans » ?', 'mcq', '["You will can vote at 18.","You will may vote at 18.","You will be allowed to vote at 18.","You will allowed to vote at 18."]'::jsonb, 2, 'Can et may n’ont pas de futur : on emploie be allowed to, qui se conjugue à tous les temps.', 2),
    ('56339aae-4d13-5a1d-a32e-d07e34682c84'::uuid, 'anglais', '5e', 'Expression de la modalité : la permission', 'Quelle demande de permission est la plus familière ?', 'mcq', '["Can I go out?","May I come in?","Could I go out?","Would you permit me to go out?"]'::jsonb, 0, 'Can est la forme courante, entre proches. Could est plus poli, may plus formel.', 3),
    ('db709525-8141-5e5d-a7bd-05b9bdb9ddde'::uuid, 'anglais', '5e', 'Expression de la modalité : la permission', 'Que signifie « You can’t park here » ?', 'mcq', '["Ce n’est pas obligatoire","Tu ne sais pas te garer","C’est déconseillé","C’est interdit"]'::jsonb, 3, 'Can’t exprime ici le refus de permission, donc l’interdiction, et non le manque de capacité.', 4),
    ('424e6762-3bd4-514a-9235-8e926a9a8efc'::uuid, 'anglais', '4e', 'Expression de la modalité : la permission', 'Que signifie « You could go » ?', 'mcq', '["Tu as la permission d’y aller","Tu pourrais y aller : c’est une suggestion","Tu dois y aller","Tu y es allé"]'::jsonb, 1, 'Could sert à demander une permission, mais pas à l’accorder : « You could go » est une suggestion.', 1),
    ('7b127acc-5854-5848-ad71-48ae79e243e9'::uuid, 'anglais', '4e', 'Expression de la modalité : la permission', 'Comment dit-on « Tu auras le droit de voter à 18 ans » ?', 'mcq', '["You will can vote at 18.","You will may vote at 18.","You will be allowed to vote at 18.","You will allowed to vote at 18."]'::jsonb, 2, 'Can et may n’ont pas de futur : on emploie be allowed to, qui se conjugue à tous les temps.', 2),
    ('fff8f0eb-186e-5b95-8388-93f465a8daa0'::uuid, 'anglais', '4e', 'Expression de la modalité : la permission', 'Quelle demande de permission est la plus familière ?', 'mcq', '["Can I go out?","May I come in?","Could I go out?","Would you permit me to go out?"]'::jsonb, 0, 'Can est la forme courante, entre proches. Could est plus poli, may plus formel.', 3),
    ('f2f0e73c-1b38-5e97-91fe-aaff13a84297'::uuid, 'anglais', '4e', 'Expression de la modalité : la permission', 'Que signifie « You can’t park here » ?', 'mcq', '["Ce n’est pas obligatoire","Tu ne sais pas te garer","C’est déconseillé","C’est interdit"]'::jsonb, 3, 'Can’t exprime ici le refus de permission, donc l’interdiction, et non le manque de capacité.', 4),
    ('8a639ea5-4eb2-53b2-8af4-07aebb5c4f28'::uuid, 'anglais', '5e', 'Expression de la modalité : donner un conseil', 'Que signifie « The train should arrive at six » ?', 'mcq', '["Le train devrait arriver à six heures","Le train doit arriver à six heures, c’est obligatoire","Le train aurait dû arriver à six heures","Tu devrais prendre le train de six heures"]'::jsonb, 0, 'Should exprime aussi ce qui est normal ou attendu, pas seulement le conseil.', 1),
