    ('940aae68-ba3c-5c99-aacf-de9993fcfe03'::uuid, 'anglais', '5e', 'Exprimer le conditionnel', 'Quelle phrase est une condition de type 2 ?', 'mcq', '["If it rains, I’ll stay home.","If I had time, I would travel.","If I had known, I would have come.","If I will have time, I travel."]'::jsonb, 1, 'Type 2 : if + prétérit, would + base verbale. Il exprime l’irréel du présent.', 1),
