    ('fda68a5f-1f90-51d1-a96e-a3c61eda78aa'::uuid, 'anglais', '5e', 'Exprimer le conditionnel', 'Complète : « If she had left earlier, she … the train. »', 'mcq', '["would have caught","would catch","had caught","will catch"]'::jsonb, 0, 'Type 3 : if + past perfect, would have + participe passé.', 3),
