    ('50a5f4ac-3a7d-5894-87cb-05efde444118'::uuid, 'physique-chimie', '5e', 'Les montages électriques', 'Deux lampes sont montées en dérivation aux bornes d’un générateur de 6 V. Quelle est la tension aux bornes de chaque lampe ?', 'mcq', '["3 V","6 V","12 V","0 V"]'::jsonb, 1, 'En dérivation, la tension est la même dans chaque branche que celle du générateur : 6 V pour chacune.', 1),
    ('55dc396e-627c-5736-a9e3-045894e8b5c0'::uuid, 'physique-chimie', '5e', 'Les montages électriques', 'Deux lampes en série ont pour tensions 2 V et 4 V. Quelle est la tension du générateur ?', 'mcq', '["2 V","4 V","8 V","6 V"]'::jsonb, 3, 'En série, les tensions s’additionnent : U = 2 + 4 = 6 V.', 2),
    ('31a7c38a-6cfa-55f7-83ad-f88765bc40f9'::uuid, 'physique-chimie', '5e', 'Les montages électriques', 'Une intensité se sépare en deux branches qui portent 0,3 A et 0,5 A. Quelle est l’intensité dans la branche principale ?', 'mcq', '["0,2 A","0,15 A","0,8 A","0,5 A"]'::jsonb, 2, 'Loi des nœuds : l’intensité principale est la somme de celles des branches, soit 0,3 + 0,5 = 0,8 A.', 3),
    ('92eb5e1b-97f3-51da-998a-e0245b90cafa'::uuid, 'physique-chimie', '5e', 'Les montages électriques', 'Que se passe-t-il quand on ajoute une lampe identique dans un circuit en série ?', 'mcq', '["Les lampes brillent moins","Les lampes brillent plus","La tension du générateur augmente","Rien ne change"]'::jsonb, 0, 'En série, la tension du générateur se partage entre plus de lampes : chacune reçoit moins et brille moins.', 4),
    ('c24ef71e-7fe4-5ca7-b518-2c2a640af19f'::uuid, 'physique-chimie', '4e', 'Les montages électriques', 'Deux lampes sont montées en dérivation aux bornes d’un générateur de 6 V. Quelle est la tension aux bornes de chaque lampe ?', 'mcq', '["3 V","6 V","12 V","0 V"]'::jsonb, 1, 'En dérivation, la tension est la même dans chaque branche que celle du générateur : 6 V pour chacune.', 1),
    ('99cfb4a9-66a9-5fd0-8cc6-e5fbbfe719ce'::uuid, 'physique-chimie', '4e', 'Les montages électriques', 'Deux lampes en série ont pour tensions 2 V et 4 V. Quelle est la tension du générateur ?', 'mcq', '["2 V","4 V","8 V","6 V"]'::jsonb, 3, 'En série, les tensions s’additionnent : U = 2 + 4 = 6 V.', 2),
    ('d1e52274-a25d-58bc-8ffe-84d6bc417fcb'::uuid, 'physique-chimie', '4e', 'Les montages électriques', 'Une intensité se sépare en deux branches qui portent 0,3 A et 0,5 A. Quelle est l’intensité dans la branche principale ?', 'mcq', '["0,2 A","0,15 A","0,8 A","0,5 A"]'::jsonb, 2, 'Loi des nœuds : l’intensité principale est la somme de celles des branches, soit 0,3 + 0,5 = 0,8 A.', 3),
