    ('be984b24-ff36-507b-9d1d-e0ccf55beff0'::uuid, 'physique-chimie', '5e', 'La tension électrique', 'Parmi ces tensions, laquelle est celle du secteur domestique ?', 'mcq', '["230 V","1,5 V","Environ 25 V","Environ 1 000 V"]'::jsonb, 0, 'Le secteur domestique fournit 230 V, une tension mortelle. Le seuil de sécurité est d’environ 25 V, une pile bâton donne 1,5 V.', 1),
    ('82822e35-287f-595d-a0e5-6a8b4d6c5a6f'::uuid, 'physique-chimie', '5e', 'La tension électrique', 'Quelle est la tension aux bornes d’un interrupteur ouvert ?', 'mcq', '["0 V","Toute la tension du générateur","La moitié de celle du générateur","Une tension négative"]'::jsonb, 1, 'Ouvert, l’interrupteur porte toute la tension du générateur (sans courant). Fermé, sa tension est presque nulle.', 2),
    ('a6edc972-fb2c-50f3-bb3f-cff2df459f84'::uuid, 'physique-chimie', '5e', 'La tension électrique', 'Un générateur de 9 V alimente en série deux lampes. La première a 3,5 V à ses bornes. Quelle tension a la seconde ?', 'mcq', '["5,5 V","12,5 V","3,5 V","4 V"]'::jsonb, 0, 'En série, U générateur = U₁ + U₂, donc U₂ = 9 − 3,5 = 5,5 V.', 3),
    ('fe12c5f3-fabf-57a4-826f-ac40b3e44cab'::uuid, 'physique-chimie', '5e', 'La tension électrique', 'Combien de fois par seconde la tension du secteur change-t-elle de signe ?', 'mcq', '["50","25","230","100"]'::jsonb, 3, 'La fréquence est de 50 Hz : 50 périodes par seconde, et chaque période comporte deux changements de signe, soit 100 par seconde.', 4),
