    ('37355e37-030c-5775-b034-2579771d7d18'::uuid, 'physique-chimie', '4e', 'La tension électrique', 'Combien de fois par seconde la tension du secteur change-t-elle de signe ?', 'mcq', '["50","25","230","100"]'::jsonb, 3, 'La fréquence est de 50 Hz : 50 périodes par seconde, et chaque période comporte deux changements de signe, soit 100 par seconde.', 4),
    ('f294546f-5d42-527a-9447-e0ce0f771081'::uuid, 'physique-chimie', '5e', 'L’intensité électrique', 'Un appareil est traversé par un courant de 250 mA. Combien cela fait-il en ampères ?', 'mcq', '["2,5 A","25 A","0,25 A","0,025 A"]'::jsonb, 2, '1 mA = 0,001 A, donc 250 mA = 250 × 0,001 = 0,25 A.', 1),
    ('9203233b-22d4-58c7-af64-c0350069b87f'::uuid, 'physique-chimie', '5e', 'L’intensité électrique', 'Dans l’analogie avec l’eau dans un tuyau, à quoi correspond la tension ?', 'mcq', '["Au débit","À la pression","À la longueur du tuyau","Au volume d’eau"]'::jsonb, 1, 'La tension est comparable à la pression de l’eau ; l’intensité est comparable au débit.', 2),
    ('fde9013b-ec9a-57f7-ab6b-bcf65772da63'::uuid, 'physique-chimie', '5e', 'L’intensité électrique', 'Un courant de 1,2 A se sépare en deux branches. L’une porte 0,7 A. Que porte l’autre ?', 'mcq', '["0,5 A","1,9 A","0,7 A","0,6 A"]'::jsonb, 0, 'Loi des nœuds : 1,2 = 0,7 + I, donc I = 1,2 − 0,7 = 0,5 A.', 3),
    ('8ebe6cfb-5714-5cca-ad8c-c99bc76f8c97'::uuid, 'physique-chimie', '5e', 'L’intensité électrique', 'Quel dispositif de sécurité se réarme après avoir coupé le circuit ?', 'mcq', '["Le fusible","Le voltmètre","L’ampèremètre","Le disjoncteur"]'::jsonb, 3, 'Le disjoncteur coupe le circuit et se réarme. Le fusible fond et doit être remplacé.', 4),
