    ('1ba22490-8296-5018-9adc-a9b8eeeeb818'::uuid, 'physique-chimie', '5e', 'Mélanges et corps purs', 'Comment classe-t-on l’air ?', 'mcq', '["Un mélange homogène","Un mélange hétérogène","Un corps pur","Un solide"]'::jsonb, 0, 'On ne distingue pas ses constituants : c’est un mélange homogène (comme l’eau salée ou le vinaigre).', 1),
    ('8fca75f5-c568-53b1-a722-c0d895f65486'::uuid, 'physique-chimie', '5e', 'Mélanges et corps purs', 'Quel est le principe de la décantation ?', 'mcq', '["Le solide est retenu par un papier filtre","La vapeur est refroidie puis recueillie","Le constituant le plus dense tombe au fond","Tous les constituants s’évaporent"]'::jsonb, 2, 'On laisse reposer le mélange hétérogène : le constituant le plus dense se dépose au fond. Le filtre retient les solides en filtration.', 2),
    ('c95eb264-594b-5439-ba01-db9c87f58340'::uuid, 'physique-chimie', '5e', 'Mélanges et corps purs', 'Que laisse l’évaporation complète d’une eau minérale ?', 'mcq', '["Rien du tout","Un résidu de sels minéraux","Du sulfate de cuivre bleu","De l’eau distillée"]'::jsonb, 1, 'Une eau pure ne laisse aucun résidu, une eau minérale en laisse : ce résidu prouve qu’elle contient des substances dissoutes, donc que ce n’est pas un corps pur.', 3),
    ('a1f7b95e-6f03-502d-826a-8b33ea725c5e'::uuid, 'physique-chimie', '5e', 'Mélanges et corps purs', 'Comment un mélange change-t-il d’état ?', 'mcq', '["À une température fixe","À 100 °C toujours","En restant à 0 °C","Sur un intervalle de températures"]'::jsonb, 3, 'Un corps pur change d’état à température constante (palier). Un mélange change d’état sur un intervalle de températures.', 4),
    ('122115e1-1250-53fd-8f39-db421ed0f525'::uuid, 'physique-chimie', '4e', 'Mélanges et corps purs', 'Comment classe-t-on l’air ?', 'mcq', '["Un mélange homogène","Un mélange hétérogène","Un corps pur","Un solide"]'::jsonb, 0, 'On ne distingue pas ses constituants : c’est un mélange homogène (comme l’eau salée ou le vinaigre).', 1),
