    ('e623bd88-6432-563e-b497-0732398a5227'::uuid, 'physique-chimie', '4e', 'La composition de l’air', 'Quelle est la valeur de la pression atmosphérique au niveau de la mer ?', 'mcq', '["101 hPa","1 013 hPa","10 130 hPa","1 013 N"]'::jsonb, 1, 'La pression atmosphérique au niveau de la mer vaut environ 1 013 hPa ; elle se mesure avec un baromètre.', 4),
    ('aa35780b-fce3-5c65-8aa5-2b135b950b66'::uuid, 'physique-chimie', '5e', 'La masse volumique', 'Un objet de 200 g occupe 25 cm³. Quelle est sa masse volumique ?', 'mcq', '["0,125 g/cm³","5 000 g/cm³","8 g/cm³","225 g/cm³"]'::jsonb, 2, 'ρ = m ÷ V = 200 ÷ 25 = 8 g/cm³, valeur proche de celle du fer (7,9 g/cm³).', 1),
    ('a15264a6-8b71-5198-9822-37eed615926c'::uuid, 'physique-chimie', '5e', 'La masse volumique', 'Quelle est la masse de 50 cm³ d’huile de masse volumique 0,92 g/cm³ ?', 'mcq', '["46 g","54 g","0,018 g","4,6 g"]'::jsonb, 0, 'De ρ = m ÷ V on tire m = ρ × V = 0,92 × 50 = 46 g.', 2),
    ('aac90a2a-b40d-5ceb-9fed-a6867aa4bcbc'::uuid, 'physique-chimie', '5e', 'La masse volumique', 'Le fer a une masse volumique de 7,9 g/cm³. Quelle est-elle en kg/m³ ?', 'mcq', '["790 kg/m³","79 kg/m³","0,0079 kg/m³","7 900 kg/m³"]'::jsonb, 3, '1 g/cm³ = 1 000 kg/m³, donc 7,9 g/cm³ = 7 900 kg/m³.', 3),
    ('f01bcd21-15f1-5029-8a67-33a9cc4c67d0'::uuid, 'physique-chimie', '5e', 'La masse volumique', 'Un morceau de bois flotte sur l’eau. Que peut-on en déduire ?', 'mcq', '["Sa masse est inférieure à 1 g","Sa masse volumique est inférieure à 1 g/cm³","Son volume est toujours inférieur à celui de l’eau","Il est nécessairement creux"]'::jsonb, 1, 'Un corps flotte si sa masse volumique est inférieure à celle du liquide (1 g/cm³ pour l’eau). La masse seule ne dit rien.', 4),
    ('433731f2-92dc-5ccf-980a-2f85e806ea42'::uuid, 'physique-chimie', '4e', 'La masse volumique', 'Un objet de 200 g occupe 25 cm³. Quelle est sa masse volumique ?', 'mcq', '["0,125 g/cm³","5 000 g/cm³","8 g/cm³","225 g/cm³"]'::jsonb, 2, 'ρ = m ÷ V = 200 ÷ 25 = 8 g/cm³, valeur proche de celle du fer (7,9 g/cm³).', 1),
    ('712d2a3f-af9e-5cf6-9504-7364ec9ca71c'::uuid, 'physique-chimie', '4e', 'La masse volumique', 'Quelle est la masse de 50 cm³ d’huile de masse volumique 0,92 g/cm³ ?', 'mcq', '["46 g","54 g","0,018 g","4,6 g"]'::jsonb, 0, 'De ρ = m ÷ V on tire m = ρ × V = 0,92 × 50 = 46 g.', 2),
    ('418bd13c-5115-5e68-8601-3431a7ef3abe'::uuid, 'physique-chimie', '4e', 'La masse volumique', 'Le fer a une masse volumique de 7,9 g/cm³. Quelle est-elle en kg/m³ ?', 'mcq', '["790 kg/m³","79 kg/m³","0,0079 kg/m³","7 900 kg/m³"]'::jsonb, 3, '1 g/cm³ = 1 000 kg/m³, donc 7,9 g/cm³ = 7 900 kg/m³.', 3),
    ('251d602c-506e-5883-8f8c-000b7a7e225e'::uuid, 'physique-chimie', '4e', 'La masse volumique', 'Un morceau de bois flotte sur l’eau. Que peut-on en déduire ?', 'mcq', '["Sa masse est inférieure à 1 g","Sa masse volumique est inférieure à 1 g/cm³","Son volume est toujours inférieur à celui de l’eau","Il est nécessairement creux"]'::jsonb, 1, 'Un corps flotte si sa masse volumique est inférieure à celle du liquide (1 g/cm³ pour l’eau). La masse seule ne dit rien.', 4),
    ('0a40dfe6-8df3-5883-b9db-7654b82d2748'::uuid, 'physique-chimie', '5e', 'Signal et information', 'Combien d’octets contient un fichier de 2 ko ?', 'mcq', '["16 octets","2 000 octets","2 000 000 octets","200 octets"]'::jsonb, 1, '1 ko = 1 000 octets, donc 2 ko = 2 000 octets (et 1 octet = 8 bits).', 1),
    ('b95cffef-d8c4-5e84-8404-d0f908f4f0d2'::uuid, 'physique-chimie', '5e', 'Signal et information', 'Dans un objet connecté, quel élément agit sur l’environnement ?', 'mcq', '["Le capteur","Le microcontrôleur","L’émetteur","L’actionneur"]'::jsonb, 3, 'Le capteur mesure, le microcontrôleur traite le signal, l’actionneur agit (moteur, lampe, alarme).', 2),
    ('922a3d39-f8b8-55a7-9544-e1ae75913d4a'::uuid, 'physique-chimie', '5e', 'Signal et information', 'Quel est un avantage du signal numérique sur le signal analogique ?', 'mcq', '["Il se copie sans perte","Il varie de façon continue","Il se dégrade à chaque copie","Il ne peut pas être compressé"]'::jsonb, 0, 'Le signal numérique, une suite de 0 et de 1, se copie sans perte et se compresse : c’est pourquoi photo, musique et télévision sont passées au numérique.', 3),
    ('943de28a-c405-5dee-a88b-e2b08b8f857a'::uuid, 'physique-chimie', '5e', 'Signal et information', 'Quel schéma décrit une chaîne de transmission ?', 'mcq', '["Récepteur → milieu → émetteur","Milieu → émetteur → récepteur","Émetteur → milieu de propagation → récepteur","Capteur → émetteur → écran"]'::jsonb, 2, 'Un signal va d’un émetteur vers un récepteur en traversant un milieu de propagation, sans transport de matière.', 4),
    ('d43c8168-932f-5b03-8b0e-670f88954ab2'::uuid, 'physique-chimie', '4e', 'Signal et information', 'Combien d’octets contient un fichier de 2 ko ?', 'mcq', '["16 octets","2 000 octets","2 000 000 octets","200 octets"]'::jsonb, 1, '1 ko = 1 000 octets, donc 2 ko = 2 000 octets (et 1 octet = 8 bits).', 1),
    ('9c44a3fd-4ec1-5666-8fef-3ffb9a6605b9'::uuid, 'physique-chimie', '4e', 'Signal et information', 'Dans un objet connecté, quel élément agit sur l’environnement ?', 'mcq', '["Le capteur","Le microcontrôleur","L’émetteur","L’actionneur"]'::jsonb, 3, 'Le capteur mesure, le microcontrôleur traite le signal, l’actionneur agit (moteur, lampe, alarme).', 2),
    ('0b1b4a8e-9ea1-56b4-bb31-98ebb7909c5f'::uuid, 'physique-chimie', '4e', 'Signal et information', 'Quel est un avantage du signal numérique sur le signal analogique ?', 'mcq', '["Il se copie sans perte","Il varie de façon continue","Il se dégrade à chaque copie","Il ne peut pas être compressé"]'::jsonb, 0, 'Le signal numérique, une suite de 0 et de 1, se copie sans perte et se compresse : c’est pourquoi photo, musique et télévision sont passées au numérique.', 3),
    ('0c1408d8-b506-54de-ae2e-71c68648ad5e'::uuid, 'physique-chimie', '4e', 'Signal et information', 'Quel schéma décrit une chaîne de transmission ?', 'mcq', '["Récepteur → milieu → émetteur","Milieu → émetteur → récepteur","Émetteur → milieu de propagation → récepteur","Capteur → émetteur → écran"]'::jsonb, 2, 'Un signal va d’un émetteur vers un récepteur en traversant un milieu de propagation, sans transport de matière.', 4),
    ('8208d782-58c0-5452-8a1d-e8751ffd6063'::uuid, 'physique-chimie', '5e', 'La lumière', 'La Lune est-elle une source primaire de lumière ?', 'mcq', '["Oui, elle produit sa propre lumière","Non, c’est un objet diffusant","Oui, mais seulement la nuit","Non, car elle est transparente"]'::jsonb, 1, 'La Lune diffuse la lumière du Soleil : c’est un objet diffusant, pas une source primaire (comme un mur ou une page de livre).', 1),
    ('edc63c8f-2973-52b0-95e8-19ba7010dbae'::uuid, 'physique-chimie', '5e', 'La lumière', 'Qu’appelle-t-on une ombre portée ?', 'mcq', '["La face non éclairée de l’objet","Une image renversée dans une boîte","La zone entourant l’objet éclairée","L’ombre formée sur le sol ou un écran"]'::jsonb, 3, 'L’ombre portée se forme sur le sol ou l’écran ; la face non éclairée de l’objet est l’ombre propre.', 2),
    ('aa165d1b-c549-552b-b4e2-6239dccae22c'::uuid, 'physique-chimie', '5e', 'La lumière', 'Quelles sont les couleurs primaires de la synthèse soustractive (peinture) ?', 'mcq', '["Cyan, magenta, jaune","Rouge, vert, bleu","Rouge, jaune, bleu","Noir, blanc, gris"]'::jsonb, 0, 'En peinture, chaque pigment retire des couleurs à la lumière blanche : les primaires sont cyan, magenta et jaune. Rouge, vert, bleu sont celles de la synthèse additive (écrans).', 3),
    ('66b82b54-cedc-5b52-9e19-080fd119f315'::uuid, 'physique-chimie', '5e', 'La lumière', 'Dans un arc-en-ciel, qu’est-ce qui disperse la lumière blanche ?', 'mcq', '["La chaleur du Soleil","Le vent","Les gouttes d’eau","La poussière"]'::jsonb, 2, 'Les gouttes d’eau jouent le rôle d’un prisme : elles dispersent la lumière blanche en un spectre continu de couleurs.', 4),
    ('57b23c26-9b14-5118-b334-1b7cdc914fd8'::uuid, 'physique-chimie', '4e', 'La lumière', 'La Lune est-elle une source primaire de lumière ?', 'mcq', '["Oui, elle produit sa propre lumière","Non, c’est un objet diffusant","Oui, mais seulement la nuit","Non, car elle est transparente"]'::jsonb, 1, 'La Lune diffuse la lumière du Soleil : c’est un objet diffusant, pas une source primaire (comme un mur ou une page de livre).', 1),
    ('f9b765e8-f902-57f4-8819-969e2d5424a9'::uuid, 'physique-chimie', '4e', 'La lumière', 'Qu’appelle-t-on une ombre portée ?', 'mcq', '["La face non éclairée de l’objet","Une image renversée dans une boîte","La zone entourant l’objet éclairée","L’ombre formée sur le sol ou un écran"]'::jsonb, 3, 'L’ombre portée se forme sur le sol ou l’écran ; la face non éclairée de l’objet est l’ombre propre.', 2),
    ('3c9456ae-21a8-5cb1-a63a-d2159417db9a'::uuid, 'physique-chimie', '4e', 'La lumière', 'Quelles sont les couleurs primaires de la synthèse soustractive (peinture) ?', 'mcq', '["Cyan, magenta, jaune","Rouge, vert, bleu","Rouge, jaune, bleu","Noir, blanc, gris"]'::jsonb, 0, 'En peinture, chaque pigment retire des couleurs à la lumière blanche : les primaires sont cyan, magenta et jaune. Rouge, vert, bleu sont celles de la synthèse additive (écrans).', 3),
    ('44d2d437-b867-5282-bb7c-ff9b15da0a91'::uuid, 'physique-chimie', '4e', 'La lumière', 'Dans un arc-en-ciel, qu’est-ce qui disperse la lumière blanche ?', 'mcq', '["La chaleur du Soleil","Le vent","Les gouttes d’eau","La poussière"]'::jsonb, 2, 'Les gouttes d’eau jouent le rôle d’un prisme : elles dispersent la lumière blanche en un spectre continu de couleurs.', 4),
    ('e2991f73-d1e9-5d7c-9e00-563621f75781'::uuid, 'physique-chimie', '5e', 'Le son', 'Dans un orage, 6 s s’écoulent entre l’éclair et le tonnerre. À quelle distance est l’éclair ?', 'mcq', '["6 km","0,5 km","20 km","2 km"]'::jsonb, 3, 'On divise le nombre de secondes par 3 : 6 ÷ 3 = 2 km. En effet d = 340 × 6 ≈ 2 040 m.', 1),
    ('3e0ef471-5c33-5114-9e82-a4435e21c3b0'::uuid, 'physique-chimie', '5e', 'Le son', 'Un sonar reçoit l’écho d’un son 2 s après son émission dans l’eau (1 500 m/s). À quelle distance est l’obstacle ?', 'mcq', '["3 000 m","1 500 m","750 m","300 m"]'::jsonb, 1, 'Le son fait l’aller-retour : distance totale 1 500 × 2 = 3 000 m, donc l’obstacle est à la moitié, soit 1 500 m.', 2),
    ('22b975c0-a182-567c-a59b-035f2dedbdce'::uuid, 'physique-chimie', '5e', 'Le son', 'Dans lequel de ces milieux le son se propage-t-il le plus vite ?', 'mcq', '["L’air","L’eau","L’acier","Le vide"]'::jsonb, 2, 'Le son va d’autant plus vite que le milieu est dense et rigide : environ 340 m/s dans l’air, 1 500 m/s dans l’eau, 5 000 m/s dans l’acier. Il ne se propage pas dans le vide.', 3),
    ('1ced09d0-9190-5ee5-a63b-45268ab4f0a1'::uuid, 'physique-chimie', '5e', 'Le son', 'À quoi sert l’expérience de la cloche à vide ?', 'mcq', '["À montrer que le son ne se propage pas dans le vide","À mesurer la vitesse du son","À amplifier une sonnerie","À mesurer le niveau sonore"]'::jsonb, 0, 'Quand on pompe l’air, la sonnerie s’éteint alors qu’on voit toujours le marteau frapper : le son a besoin d’un milieu matériel.', 4),
    ('e80d88e7-a33c-53df-83d1-715c261b498f'::uuid, 'physique-chimie', '4e', 'Le son', 'Dans un orage, 6 s s’écoulent entre l’éclair et le tonnerre. À quelle distance est l’éclair ?', 'mcq', '["6 km","0,5 km","20 km","2 km"]'::jsonb, 3, 'On divise le nombre de secondes par 3 : 6 ÷ 3 = 2 km. En effet d = 340 × 6 ≈ 2 040 m.', 1),
    ('6b7c6e5a-df52-502d-bf95-0233c2bbf47a'::uuid, 'physique-chimie', '4e', 'Le son', 'Un sonar reçoit l’écho d’un son 2 s après son émission dans l’eau (1 500 m/s). À quelle distance est l’obstacle ?', 'mcq', '["3 000 m","1 500 m","750 m","300 m"]'::jsonb, 1, 'Le son fait l’aller-retour : distance totale 1 500 × 2 = 3 000 m, donc l’obstacle est à la moitié, soit 1 500 m.', 2),
    ('e8c46c36-7141-5d33-bdd1-2263b8bfa00e'::uuid, 'physique-chimie', '4e', 'Le son', 'Dans lequel de ces milieux le son se propage-t-il le plus vite ?', 'mcq', '["L’air","L’eau","L’acier","Le vide"]'::jsonb, 2, 'Le son va d’autant plus vite que le milieu est dense et rigide : environ 340 m/s dans l’air, 1 500 m/s dans l’eau, 5 000 m/s dans l’acier. Il ne se propage pas dans le vide.', 3),
    ('5f591714-7ecf-5654-8f09-0832b1993195'::uuid, 'physique-chimie', '4e', 'Le son', 'À quoi sert l’expérience de la cloche à vide ?', 'mcq', '["À montrer que le son ne se propage pas dans le vide","À mesurer la vitesse du son","À amplifier une sonnerie","À mesurer le niveau sonore"]'::jsonb, 0, 'Quand on pompe l’air, la sonnerie s’éteint alors qu’on voit toujours le marteau frapper : le son a besoin d’un milieu matériel.', 4),
    ('226e27d6-0405-586d-b9a7-9022c6bd3886'::uuid, 'physique-chimie', '5e', 'Les signaux sonores', 'Quelle est la période d’un son de fréquence 1 000 Hz ?', 'mcq', '["1 s","0,1 ms","1 ms","10 ms"]'::jsonb, 2, 'T = 1 ÷ f = 1 ÷ 1 000 = 0,001 s = 1 ms.', 1),
    ('b63074e3-446b-502f-8103-7a61499e4659'::uuid, 'physique-chimie', '5e', 'Les signaux sonores', 'Deux notes ont pour périodes 2 ms et 4 ms. Laquelle est la plus aiguë ?', 'mcq', '["Celle de période 4 ms","Celle de période 2 ms","Elles sont identiques","Celle de plus grande amplitude"]'::jsonb, 1, 'Plus la période est courte, plus la fréquence est grande et plus le son est aigu : 2 ms correspond à 500 Hz, 4 ms à 250 Hz.', 2),
    ('8b11dfda-05ca-5735-be5c-3ad16118cad2'::uuid, 'physique-chimie', '5e', 'Les signaux sonores', 'Que sont les infrasons ?', 'mcq', '["Des sons de fréquence supérieure à 20 000 Hz","Des sons compris entre 20 et 20 000 Hz","Des sons de fréquence toujours nulle","Des sons de fréquence inférieure à 20 Hz"]'::jsonb, 3, 'Les infrasons ont une fréquence inférieure à 20 Hz (éléphants, séismes). Au-delà de 20 000 Hz, ce sont des ultrasons.', 3),
    ('43a39ba6-16e9-5d8f-820e-68d0ede73a8c'::uuid, 'physique-chimie', '5e', 'Les signaux sonores', 'Sur l’écran d’un oscilloscope, qu’est-ce qui montre qu’un son est plus fort ?', 'mcq', '["Une amplitude plus grande","Une période plus courte","Une fréquence plus grande","Une courbe sans période"]'::jsonb, 0, 'Plus l’amplitude est grande, plus le son est fort. Elle ne change pas la hauteur du son, liée à la fréquence.', 4),
    ('9a172cbd-16f0-5303-82f0-24e483d554de'::uuid, 'physique-chimie', '4e', 'Les signaux sonores', 'Quelle est la période d’un son de fréquence 1 000 Hz ?', 'mcq', '["1 s","0,1 ms","1 ms","10 ms"]'::jsonb, 2, 'T = 1 ÷ f = 1 ÷ 1 000 = 0,001 s = 1 ms.', 1),
    ('f73fec7a-99c7-576d-83a5-d6c86417a0ce'::uuid, 'physique-chimie', '4e', 'Les signaux sonores', 'Deux notes ont pour périodes 2 ms et 4 ms. Laquelle est la plus aiguë ?', 'mcq', '["Celle de période 4 ms","Celle de période 2 ms","Elles sont identiques","Celle de plus grande amplitude"]'::jsonb, 1, 'Plus la période est courte, plus la fréquence est grande et plus le son est aigu : 2 ms correspond à 500 Hz, 4 ms à 250 Hz.', 2),
    ('8e342d34-bc4e-50f9-9513-67b64a12e9d1'::uuid, 'physique-chimie', '4e', 'Les signaux sonores', 'Que sont les infrasons ?', 'mcq', '["Des sons de fréquence supérieure à 20 000 Hz","Des sons compris entre 20 et 20 000 Hz","Des sons de fréquence toujours nulle","Des sons de fréquence inférieure à 20 Hz"]'::jsonb, 3, 'Les infrasons ont une fréquence inférieure à 20 Hz (éléphants, séismes). Au-delà de 20 000 Hz, ce sont des ultrasons.', 3),
    ('0460cdcb-b43c-5915-9378-e930075b68ae'::uuid, 'physique-chimie', '4e', 'Les signaux sonores', 'Sur l’écran d’un oscilloscope, qu’est-ce qui montre qu’un son est plus fort ?', 'mcq', '["Une amplitude plus grande","Une période plus courte","Une fréquence plus grande","Une courbe sans période"]'::jsonb, 0, 'Plus l’amplitude est grande, plus le son est fort. Elle ne change pas la hauteur du son, liée à la fréquence.', 4),
    ('d79becfa-d6b4-5666-a51f-7de316fba742'::uuid, 'physique-chimie', '5e', 'Les atomes et la transformation chimique', 'Combien d’atomes d’oxygène représente l’écriture 2 O₂ ?', 'mcq', '["2","3","4","8"]'::jsonb, 2, 'Le nombre devant la formule multiplie la molécule : 2 molécules O₂ contiennent 2 × 2 = 4 atomes d’oxygène.', 1),
    ('7eabc2f7-42ff-5386-9d9b-2e70794ebedc'::uuid, 'physique-chimie', '5e', 'Les atomes et la transformation chimique', 'Lequel de ces signes indique une transformation chimique ?', 'mcq', '["Un changement d’état","Un dégagement de gaz","Une dissolution de sucre","Une variation de volume"]'::jsonb, 1, 'Dégagement de gaz, changement de couleur, précipité, dégagement de chaleur ou disparition d’un réactif signalent une transformation chimique.', 2),
    ('b3db7806-bab0-5ec4-b5f1-41660f34251a'::uuid, 'physique-chimie', '5e', 'Les atomes et la transformation chimique', '6 g de carbone réagissent entièrement avec 16 g de dioxygène pour donner du dioxyde de carbone. Quelle masse de CO₂ se forme ?', 'mcq', '["10 g","96 g","16 g","22 g"]'::jsonb, 3, 'Loi de Lavoisier : la masse totale se conserve, donc masse des produits = 6 + 16 = 22 g.', 3),
    ('4f05458f-4cb7-56f9-b9f3-10156462794c'::uuid, 'physique-chimie', '5e', 'Les atomes et la transformation chimique', 'Complète l’équation ajustée : 2 H₂ + O₂ → … H₂O', 'mcq', '["2 H₂O","H₂O","4 H₂O","3 H₂O"]'::jsonb, 0, 'À gauche, 4 atomes d’hydrogène et 2 d’oxygène ; il faut donc 2 molécules H₂O à droite (4 H et 2 O).', 4),
    ('f0faf001-dbe2-56bd-9352-a839cd796d6d'::uuid, 'physique-chimie', '4e', 'Les atomes et la transformation chimique', 'Combien d’atomes d’oxygène représente l’écriture 2 O₂ ?', 'mcq', '["2","3","4","8"]'::jsonb, 2, 'Le nombre devant la formule multiplie la molécule : 2 molécules O₂ contiennent 2 × 2 = 4 atomes d’oxygène.', 1),
    ('47215cd6-ccbb-5fe3-9b19-c8ab4379ef1f'::uuid, 'physique-chimie', '4e', 'Les atomes et la transformation chimique', 'Lequel de ces signes indique une transformation chimique ?', 'mcq', '["Un changement d’état","Un dégagement de gaz","Une dissolution de sucre","Une variation de volume"]'::jsonb, 1, 'Dégagement de gaz, changement de couleur, précipité, dégagement de chaleur ou disparition d’un réactif signalent une transformation chimique.', 2),
    ('0ce7b047-298f-5571-bf7f-e255d5f7b0e6'::uuid, 'physique-chimie', '4e', 'Les atomes et la transformation chimique', '6 g de carbone réagissent entièrement avec 16 g de dioxygène pour donner du dioxyde de carbone. Quelle masse de CO₂ se forme ?', 'mcq', '["10 g","96 g","16 g","22 g"]'::jsonb, 3, 'Loi de Lavoisier : la masse totale se conserve, donc masse des produits = 6 + 16 = 22 g.', 3),
    ('6f875ce3-032f-5d5f-962d-b1e20149e22d'::uuid, 'physique-chimie', '4e', 'Les atomes et la transformation chimique', 'Complète l’équation ajustée : 2 H₂ + O₂ → … H₂O', 'mcq', '["2 H₂O","H₂O","4 H₂O","3 H₂O"]'::jsonb, 0, 'À gauche, 4 atomes d’hydrogène et 2 d’oxygène ; il faut donc 2 molécules H₂O à droite (4 H et 2 O).', 4),
    ('685516ef-f794-52dd-9987-7ccfe50253fb'::uuid, 'physique-chimie', '5e', 'Les tests caractéristiques des espèces chimiques', 'L’eau de chaux se trouble dans un gaz. Quel gaz est identifié ?', 'mcq', '["Le dioxygène","Le dihydrogène","Le dioxyde de carbone","La vapeur d’eau"]'::jsonb, 2, 'L’eau de chaux qui se trouble (blanc laiteux) identifie le dioxyde de carbone.', 1),
    ('b49308db-1b16-5391-8b2a-a0ca72b654e1'::uuid, 'physique-chimie', '5e', 'Les tests caractéristiques des espèces chimiques', 'On ajoute de la soude à une solution : un précipité vert apparaît. Quel ion est identifié ?', 'mcq', '["Fer II","Fer III","Cuivre II","Chlorure"]'::jsonb, 0, 'Fer II : précipité vert. Fer III : rouille. Cuivre II : bleu. Zinc : blanc.', 2),
    ('17816f85-a390-5a16-92a0-82379c1d5f4d'::uuid, 'physique-chimie', '5e', 'Les tests caractéristiques des espèces chimiques', 'Que devient le précipité blanc formé par les ions chlorure et le nitrate d’argent ?', 'mcq', '["Il devient vert","Il noircit à la lumière","Il devient bleu","Il se dissout"]'::jsonb, 1, 'Le précipité de chlorure d’argent est blanc et noircit à la lumière.', 3),
    ('d827afcb-4645-5a99-89e2-571740f52772'::uuid, 'physique-chimie', '5e', 'Les tests caractéristiques des espèces chimiques', 'Quelle protection porte-t-on pour manipuler de la soude ?', 'mcq', '["Aucune protection","Des gants seulement","Un simple tablier","Lunettes, gants et blouse"]'::jsonb, 3, 'La soude est corrosive : lunettes, gants et blouse sont indispensables (comme pour le nitrate d’argent).', 4),
    ('a36de177-b4f7-5881-8fb7-30ebabf0b326'::uuid, 'physique-chimie', '4e', 'Les tests caractéristiques des espèces chimiques', 'L’eau de chaux se trouble dans un gaz. Quel gaz est identifié ?', 'mcq', '["Le dioxygène","Le dihydrogène","Le dioxyde de carbone","La vapeur d’eau"]'::jsonb, 2, 'L’eau de chaux qui se trouble (blanc laiteux) identifie le dioxyde de carbone.', 1),
    ('e770ec8a-aa8a-56d1-95ad-4d1d7ba2bb12'::uuid, 'physique-chimie', '4e', 'Les tests caractéristiques des espèces chimiques', 'On ajoute de la soude à une solution : un précipité vert apparaît. Quel ion est identifié ?', 'mcq', '["Fer II","Fer III","Cuivre II","Chlorure"]'::jsonb, 0, 'Fer II : précipité vert. Fer III : rouille. Cuivre II : bleu. Zinc : blanc.', 2),
    ('67b38abb-df2f-5280-baf3-75b077d74581'::uuid, 'physique-chimie', '4e', 'Les tests caractéristiques des espèces chimiques', 'Que devient le précipité blanc formé par les ions chlorure et le nitrate d’argent ?', 'mcq', '["Il devient vert","Il noircit à la lumière","Il devient bleu","Il se dissout"]'::jsonb, 1, 'Le précipité de chlorure d’argent est blanc et noircit à la lumière.', 3),
    ('895a5eae-bc4c-5e7e-8496-3e9b8933a297'::uuid, 'physique-chimie', '4e', 'Les tests caractéristiques des espèces chimiques', 'Quelle protection porte-t-on pour manipuler de la soude ?', 'mcq', '["Aucune protection","Des gants seulement","Un simple tablier","Lunettes, gants et blouse"]'::jsonb, 3, 'La soude est corrosive : lunettes, gants et blouse sont indispensables (comme pour le nitrate d’argent).', 4),
    ('d74a466e-f495-5b2b-ac92-c42695fc0a2c'::uuid, 'physique-chimie', '5e', 'Les ions', 'Quel est le symbole de l’ion sodium ?', 'mcq', '["Na⁻","Na⁺","Na²⁺","Cl⁺"]'::jsonb, 1, 'L’atome de sodium perd un électron : il devient un cation de charge 1+, noté Na⁺.', 1),
    ('fa32556d-7241-52c2-8857-d1bc2a7ef2db'::uuid, 'physique-chimie', '5e', 'Les ions', 'Cl⁻ est :', 'mcq', '["Un cation","Un isotope","Un atome neutre","Un anion"]'::jsonb, 3, 'Un ion négatif, qui a gagné un électron, s’appelle un anion. Un cation est positif.', 2),
    ('5a8aafca-c2bc-5cd5-aeab-f87805ad5255'::uuid, 'physique-chimie', '5e', 'Les ions', 'Que devient un atome quand il perd un électron ?', 'mcq', '["Il devient un cation, avec un proton de plus que d’électrons","Il devient un anion, avec un électron de moins que de protons","Il devient un autre élément chimique","Il reste neutre mais plus léger"]'::jsonb, 0, 'Il a perdu une charge négative : il porte un proton de trop, donc une charge positive. Le noyau ne change pas, l’élément reste le même.', 3),
    ('a055a367-7eff-5681-8958-8dbc2b2c6e0e'::uuid, 'physique-chimie', '5e', 'Les ions', 'Une solution d’eau salée est-elle électriquement chargée ?', 'mcq', '["Non, elle porte une charge positive","Non, elle porte une charge négative","Oui, autant de charges positives que négatives","Oui, mais seulement si elle est chauffée"]'::jsonb, 2, 'Elle est neutre dans son ensemble : autant de charges positives (Na⁺) que négatives (Cl⁻). Les ions restent mobiles.', 4),
    ('12bd779b-b09c-510c-8647-d45d06b21404'::uuid, 'physique-chimie', '4e', 'Les ions', 'Quel est le symbole de l’ion sodium ?', 'mcq', '["Na⁻","Na⁺","Na²⁺","Cl⁺"]'::jsonb, 1, 'L’atome de sodium perd un électron : il devient un cation de charge 1+, noté Na⁺.', 1),
    ('217e08a3-0856-57dc-8a65-90302273b580'::uuid, 'physique-chimie', '4e', 'Les ions', 'Cl⁻ est :', 'mcq', '["Un cation","Un isotope","Un atome neutre","Un anion"]'::jsonb, 3, 'Un ion négatif, qui a gagné un électron, s’appelle un anion. Un cation est positif.', 2),
    ('9c293154-cd9e-515e-b0ad-618087475537'::uuid, 'physique-chimie', '4e', 'Les ions', 'Que devient un atome quand il perd un électron ?', 'mcq', '["Il devient un cation, avec un proton de plus que d’électrons","Il devient un anion, avec un électron de moins que de protons","Il devient un autre élément chimique","Il reste neutre mais plus léger"]'::jsonb, 0, 'Il a perdu une charge négative : il porte un proton de trop, donc une charge positive. Le noyau ne change pas, l’élément reste le même.', 3),
    ('d20ade8c-cc7f-5cb5-871a-49a8506b5afd'::uuid, 'physique-chimie', '4e', 'Les ions', 'Une solution d’eau salée est-elle électriquement chargée ?', 'mcq', '["Non, elle porte une charge positive","Non, elle porte une charge négative","Oui, autant de charges positives que négatives","Oui, mais seulement si elle est chauffée"]'::jsonb, 2, 'Elle est neutre dans son ensemble : autant de charges positives (Na⁺) que négatives (Cl⁻). Les ions restent mobiles.', 4),
    ('8b793f7a-2c84-5a89-9367-b009819bb3a7'::uuid, 'physique-chimie', '5e', 'Le pH ou potentiel hydrogène', 'Une eau savonneuse a un pH d’environ 9. Comment est-elle ?', 'mcq', '["Acide","Neutre","Basique","Saturée"]'::jsonb, 2, 'pH supérieur à 7 : solution basique. Inférieur à 7 : acide. Égal à 7 : neutre.', 1),
    ('34b5b6c5-7322-5411-8d87-294ee3e6260d'::uuid, 'physique-chimie', '5e', 'Le pH ou potentiel hydrogène', 'Quelle est la précision du papier pH ?', 'mcq', '["Au centième","Environ 1 unité","Au dixième","Exacte"]'::jsonb, 1, 'Le papier pH donne le pH à environ 1 unité près ; le pH-mètre est précis au dixième.', 2),
    ('6f645148-1436-58b4-9501-9bf1a510496c'::uuid, 'physique-chimie', '5e', 'Le pH ou potentiel hydrogène', 'Quels ions dominent dans une solution basique ?', 'mcq', '["Les ions hydroxyde OH⁻","Les ions hydrogène H⁺","Les ions chlorure Cl⁻","Les ions sodium seulement"]'::jsonb, 0, 'Une solution basique contient surtout des ions hydroxyde OH⁻ ; une solution acide, des ions hydrogène H⁺.', 3),
    ('5b29c5b6-c127-504c-b7d2-80c70f6b1442'::uuid, 'physique-chimie', '5e', 'Le pH ou potentiel hydrogène', 'On dilue beaucoup une solution basique de pH 13. Que devient son pH ?', 'mcq', '["Il devient inférieur à 7","Il augmente au-delà de 13","Il reste à 13","Il diminue en se rapprochant de 7"]'::jsonb, 3, 'La dilution rapproche le pH de 7 sans jamais le dépasser : on ne rend pas une solution basique acide en la diluant.', 4),
    ('67d94c78-b4a4-5dfa-a67e-c242ac81cb03'::uuid, 'physique-chimie', '4e', 'Le pH ou potentiel hydrogène', 'Une eau savonneuse a un pH d’environ 9. Comment est-elle ?', 'mcq', '["Acide","Neutre","Basique","Saturée"]'::jsonb, 2, 'pH supérieur à 7 : solution basique. Inférieur à 7 : acide. Égal à 7 : neutre.', 1),
    ('4442ddde-be45-54d3-8403-cdb95a2d2c12'::uuid, 'physique-chimie', '4e', 'Le pH ou potentiel hydrogène', 'Quelle est la précision du papier pH ?', 'mcq', '["Au centième","Environ 1 unité","Au dixième","Exacte"]'::jsonb, 1, 'Le papier pH donne le pH à environ 1 unité près ; le pH-mètre est précis au dixième.', 2),
    ('fa2b7824-e353-5731-be6a-afb2ea313e5e'::uuid, 'physique-chimie', '4e', 'Le pH ou potentiel hydrogène', 'Quels ions dominent dans une solution basique ?', 'mcq', '["Les ions hydroxyde OH⁻","Les ions hydrogène H⁺","Les ions chlorure Cl⁻","Les ions sodium seulement"]'::jsonb, 0, 'Une solution basique contient surtout des ions hydroxyde OH⁻ ; une solution acide, des ions hydrogène H⁺.', 3),
    ('5a6d6386-1347-5b35-9793-2fb55f87fec3'::uuid, 'physique-chimie', '4e', 'Le pH ou potentiel hydrogène', 'On dilue beaucoup une solution basique de pH 13. Que devient son pH ?', 'mcq', '["Il devient inférieur à 7","Il augmente au-delà de 13","Il reste à 13","Il diminue en se rapprochant de 7"]'::jsonb, 3, 'La dilution rapproche le pH de 7 sans jamais le dépasser : on ne rend pas une solution basique acide en la diluant.', 4),
    ('b33488dd-71eb-597f-bf41-7b2a06159a78'::uuid, 'physique-chimie', '5e', 'Les réactions aux solutions acides', 'Dans la réaction de l’acide chlorhydrique avec le fer, quel est l’ion spectateur ?', 'mcq', '["H⁺","Fe²⁺","Cl⁻","OH⁻"]'::jsonb, 2, 'L’ion chlorure Cl⁻ ne participe pas à la réaction : c’est un ion spectateur. Les ions H⁺ réagissent avec le fer.', 1),
    ('1f613cf0-4074-5a1f-9dad-a66285606716'::uuid, 'physique-chimie', '5e', 'Les réactions aux solutions acides', 'Que se passe-t-il quand on met du zinc dans l’acide chlorhydrique ?', 'mcq', '["Il réagit avec dégagement de dihydrogène","Il ne réagit pas","Il dégage du dioxygène","Il se dissout sans rien produire"]'::jsonb, 0, 'Zinc, aluminium et magnésium réagissent avec l’acide chlorhydrique en dégageant du dihydrogène.', 2),
    ('11a197d6-e89f-5ab1-a0cd-239aefab875b'::uuid, 'physique-chimie', '5e', 'Les réactions aux solutions acides', 'Comment est la masse de rouille formée par rapport au fer disparu ?', 'mcq', '["Égale à celle du fer disparu","Supérieure, car des atomes d’oxygène s’y ajoutent","Inférieure, car du fer est perdu","Nulle : la rouille est légère"]'::jsonb, 1, 'La rouille contient du fer et de l’oxygène : sa masse est supérieure à celle du fer disparu. Le fer ne s’use pas, il se transforme.', 3),
    ('19cdf90a-0e79-55c0-91b3-d07734770560'::uuid, 'physique-chimie', '5e', 'Les réactions aux solutions acides', 'Lequel de ces métaux est attaqué par l’acide chlorhydrique ?', 'mcq', '["L’or","L’argent","Le cuivre","L’aluminium"]'::jsonb, 3, 'Cuivre, or et argent ne réagissent pas avec l’acide chlorhydrique ; l’aluminium, le zinc et le magnésium, si.', 4),
    ('df46e678-4d54-5fbc-9d49-a7e47b2ee6a9'::uuid, 'physique-chimie', '4e', 'Les réactions aux solutions acides', 'Dans la réaction de l’acide chlorhydrique avec le fer, quel est l’ion spectateur ?', 'mcq', '["H⁺","Fe²⁺","Cl⁻","OH⁻"]'::jsonb, 2, 'L’ion chlorure Cl⁻ ne participe pas à la réaction : c’est un ion spectateur. Les ions H⁺ réagissent avec le fer.', 1),
    ('9349d4ba-7dda-5e33-835e-5673203f1f45'::uuid, 'physique-chimie', '4e', 'Les réactions aux solutions acides', 'Que se passe-t-il quand on met du zinc dans l’acide chlorhydrique ?', 'mcq', '["Il réagit avec dégagement de dihydrogène","Il ne réagit pas","Il dégage du dioxygène","Il se dissout sans rien produire"]'::jsonb, 0, 'Zinc, aluminium et magnésium réagissent avec l’acide chlorhydrique en dégageant du dihydrogène.', 2),
    ('11e00cc7-1f25-594c-82b1-b9665b46ae1c'::uuid, 'physique-chimie', '4e', 'Les réactions aux solutions acides', 'Comment est la masse de rouille formée par rapport au fer disparu ?', 'mcq', '["Égale à celle du fer disparu","Supérieure, car des atomes d’oxygène s’y ajoutent","Inférieure, car du fer est perdu","Nulle : la rouille est légère"]'::jsonb, 1, 'La rouille contient du fer et de l’oxygène : sa masse est supérieure à celle du fer disparu. Le fer ne s’use pas, il se transforme.', 3),
    ('24793806-a6b6-555c-8359-8adbce7a99d5'::uuid, 'physique-chimie', '4e', 'Les réactions aux solutions acides', 'Lequel de ces métaux est attaqué par l’acide chlorhydrique ?', 'mcq', '["L’or","L’argent","Le cuivre","L’aluminium"]'::jsonb, 3, 'Cuivre, or et argent ne réagissent pas avec l’acide chlorhydrique ; l’aluminium, le zinc et le magnésium, si.', 4),
    ('bc80ae5d-f665-5599-8ef8-f28c04038cf4'::uuid, 'physique-chimie', '5e', 'Les mouvements', 'Un train parcourt 150 km en 2 h. Quelle est sa vitesse moyenne ?', 'mcq', '["300 km/h","75 km/h","0,013 km/h","152 km/h"]'::jsonb, 1, 'v = d ÷ t = 150 ÷ 2 = 75 km/h.', 1),
    ('8a6f6cb2-800d-5328-ac7f-b43899bfbee0'::uuid, 'physique-chimie', '5e', 'Les mouvements', 'Quelle est la vitesse de 54 km/h en m/s ?', 'mcq', '["194,4 m/s","5,4 m/s","15 m/s","54 m/s"]'::jsonb, 2, 'On divise par 3,6 : 54 ÷ 3,6 = 15 m/s.', 2),
    ('b68f29dd-ce92-5ef8-b3da-60a638dc78a0'::uuid, 'physique-chimie', '5e', 'Les mouvements', 'Un cycliste roule à 20 m/s à vitesse constante pendant 30 s. Quelle distance parcourt-il ?', 'mcq', '["600 m","0,67 m","50 m","6 000 m"]'::jsonb, 0, 'd = v × t = 20 × 30 = 600 m.', 3),
    ('b40f97e5-8451-587a-b4ac-986e412ebdbb'::uuid, 'physique-chimie', '5e', 'Les mouvements', 'Sur une chronophotographie, les positions successives d’un objet sont régulièrement espacées. Que peut-on dire de son mouvement ?', 'mcq', '["Il est accéléré","Il est ralenti","Il est immobile","Il est uniforme"]'::jsonb, 3, 'Des positions à intervalles de temps égaux et à distances égales indiquent une vitesse constante : un mouvement uniforme.', 4),
    ('e27e556a-989f-57d6-86f4-df8f6dd86d44'::uuid, 'physique-chimie', '4e', 'Les mouvements', 'Un train parcourt 150 km en 2 h. Quelle est sa vitesse moyenne ?', 'mcq', '["300 km/h","75 km/h","0,013 km/h","152 km/h"]'::jsonb, 1, 'v = d ÷ t = 150 ÷ 2 = 75 km/h.', 1),
    ('55ef6844-3e4a-5721-8f70-3b05116978df'::uuid, 'physique-chimie', '4e', 'Les mouvements', 'Quelle est la vitesse de 54 km/h en m/s ?', 'mcq', '["194,4 m/s","5,4 m/s","15 m/s","54 m/s"]'::jsonb, 2, 'On divise par 3,6 : 54 ÷ 3,6 = 15 m/s.', 2),
    ('0458f743-1c13-52ab-8384-d3aa32411963'::uuid, 'physique-chimie', '4e', 'Les mouvements', 'Un cycliste roule à 20 m/s à vitesse constante pendant 30 s. Quelle distance parcourt-il ?', 'mcq', '["600 m","0,67 m","50 m","6 000 m"]'::jsonb, 0, 'd = v × t = 20 × 30 = 600 m.', 3),
    ('6af9f702-f0da-525e-85c2-d91b80166235'::uuid, 'physique-chimie', '4e', 'Les mouvements', 'Sur une chronophotographie, les positions successives d’un objet sont régulièrement espacées. Que peut-on dire de son mouvement ?', 'mcq', '["Il est accéléré","Il est ralenti","Il est immobile","Il est uniforme"]'::jsonb, 3, 'Des positions à intervalles de temps égaux et à distances égales indiquent une vitesse constante : un mouvement uniforme.', 4),
    ('29ae0e75-4887-588e-bef0-7716a50134df'::uuid, 'physique-chimie', '5e', 'Interactions et forces', 'Quelle grandeur le dynamomètre mesure-t-il ?', 'mcq', '["Une masse","Une force","Une énergie","Une vitesse"]'::jsonb, 1, 'Le dynamomètre mesure la valeur d’une force, en newtons (N). La balance mesure la masse.', 1),
    ('9076bc26-6fc3-5e8a-8577-a363d450526f'::uuid, 'physique-chimie', '5e', 'Interactions et forces', 'Lequel de ces exemples est une interaction à distance ?', 'mcq', '["Le magnétisme","La poussée d’une main","Le frottement de l’air","Le sol qui soutient un objet"]'::jsonb, 0, 'Gravitation, magnétisme et électrostatique s’exercent sans contact. Les trois autres sont des interactions de contact.', 2),
    ('970f5898-b1be-5268-89c7-b0afb06c75fb'::uuid, 'physique-chimie', '5e', 'Interactions et forces', 'Un palet glisse en ligne droite à vitesse constante. Que peut-on dire des forces qui s’exercent sur lui ?', 'mcq', '["Il n’y a aucune force sur lui","Elles le font ralentir peu à peu","Elles se compensent","Elles sont toutes dirigées vers l’avant"]'::jsonb, 2, 'Une vitesse constante en ligne droite signifie que les forces se compensent. Il n’est pas nécessaire d’avoir une force pour continuer d’avancer.', 3),
    ('b2886e83-be32-5ae0-981e-bc9a6e08edde'::uuid, 'physique-chimie', '5e', 'Interactions et forces', 'Que représente la longueur de la flèche qui schématise une force ?', 'mcq', '["Le sens","La direction","Le point d’application","La valeur de la force"]'::jsonb, 3, 'La longueur de la flèche traduit la valeur de la force (en newtons). Le sens est celui de la pointe.', 4),
    ('395a635b-d57b-5d60-88a4-d21a74145245'::uuid, 'physique-chimie', '4e', 'Interactions et forces', 'Quelle grandeur le dynamomètre mesure-t-il ?', 'mcq', '["Une masse","Une force","Une énergie","Une vitesse"]'::jsonb, 1, 'Le dynamomètre mesure la valeur d’une force, en newtons (N). La balance mesure la masse.', 1),
    ('c4f1c1c9-7aae-53a4-b128-42036e6d7514'::uuid, 'physique-chimie', '4e', 'Interactions et forces', 'Lequel de ces exemples est une interaction à distance ?', 'mcq', '["Le magnétisme","La poussée d’une main","Le frottement de l’air","Le sol qui soutient un objet"]'::jsonb, 0, 'Gravitation, magnétisme et électrostatique s’exercent sans contact. Les trois autres sont des interactions de contact.', 2),
    ('fbd0372c-d89a-5a07-966b-b3f9e9e48f6a'::uuid, 'physique-chimie', '4e', 'Interactions et forces', 'Un palet glisse en ligne droite à vitesse constante. Que peut-on dire des forces qui s’exercent sur lui ?', 'mcq', '["Il n’y a aucune force sur lui","Elles le font ralentir peu à peu","Elles se compensent","Elles sont toutes dirigées vers l’avant"]'::jsonb, 2, 'Une vitesse constante en ligne droite signifie que les forces se compensent. Il n’est pas nécessaire d’avoir une force pour continuer d’avancer.', 3),
    ('ca23e958-9dfb-50d0-8703-063d9e35e571'::uuid, 'physique-chimie', '4e', 'Interactions et forces', 'Que représente la longueur de la flèche qui schématise une force ?', 'mcq', '["Le sens","La direction","Le point d’application","La valeur de la force"]'::jsonb, 3, 'La longueur de la flèche traduit la valeur de la force (en newtons). Le sens est celui de la pointe.', 4),
    ('28261ae7-6a0f-566e-8c62-63b401f6d98c'::uuid, 'physique-chimie', '5e', 'Poids et gravitation', 'Quel est le poids sur Terre d’un objet de 5 kg (g = 9,8 N/kg) ?', 'mcq', '["49 N","5 N","0,51 N","4,9 N"]'::jsonb, 0, 'P = m × g = 5 × 9,8 = 49 N.', 1),
    ('c462ce76-daa1-534a-84ea-b224075c7ee9'::uuid, 'physique-chimie', '5e', 'Poids et gravitation', 'Quel est le poids sur la Lune d’un objet de 10 kg (g = 1,6 N/kg) ?', 'mcq', '["98 N","10 N","16 N","1,6 N"]'::jsonb, 2, 'P = m × g = 10 × 1,6 = 16 N. Sa masse, elle, reste égale à 10 kg.', 2),
    ('ec05fd21-de09-55fb-9621-f367aecd13c3'::uuid, 'physique-chimie', '5e', 'Poids et gravitation', 'Un objet a un poids de 196 N sur Terre (g = 9,8 N/kg). Quelle est sa masse ?', 'mcq', '["196 kg","20 kg","2 kg","1 920 kg"]'::jsonb, 1, 'De P = m × g, on tire m = P ÷ g = 196 ÷ 9,8 = 20 kg.', 3),
    ('45026463-2202-5ea5-a049-b5b0a056e370'::uuid, 'physique-chimie', '5e', 'Poids et gravitation', 'En quel point s’applique le poids d’un objet ?', 'mcq', '["À la base de l’objet","À la surface supérieure","Au point de contact avec le sol","Au centre de gravité de l’objet"]'::jsonb, 3, 'Le poids s’applique au centre de gravité de l’objet ; il est vertical et dirigé vers le bas.', 4),
    ('1f4f69a5-d84b-551c-b3ad-50c40944aa1c'::uuid, 'physique-chimie', '4e', 'Poids et gravitation', 'Quel est le poids sur Terre d’un objet de 5 kg (g = 9,8 N/kg) ?', 'mcq', '["49 N","5 N","0,51 N","4,9 N"]'::jsonb, 0, 'P = m × g = 5 × 9,8 = 49 N.', 1),
    ('e60cb6b1-242b-522c-af72-35652ec15b81'::uuid, 'physique-chimie', '4e', 'Poids et gravitation', 'Quel est le poids sur la Lune d’un objet de 10 kg (g = 1,6 N/kg) ?', 'mcq', '["98 N","10 N","16 N","1,6 N"]'::jsonb, 2, 'P = m × g = 10 × 1,6 = 16 N. Sa masse, elle, reste égale à 10 kg.', 2),
    ('e7af5bb8-3aed-5939-af77-4a2011230fa9'::uuid, 'physique-chimie', '4e', 'Poids et gravitation', 'Un objet a un poids de 196 N sur Terre (g = 9,8 N/kg). Quelle est sa masse ?', 'mcq', '["196 kg","20 kg","2 kg","1 920 kg"]'::jsonb, 1, 'De P = m × g, on tire m = P ÷ g = 196 ÷ 9,8 = 20 kg.', 3),
    ('6e300237-73ac-5331-ae94-c5f7cea52d16'::uuid, 'physique-chimie', '4e', 'Poids et gravitation', 'En quel point s’applique le poids d’un objet ?', 'mcq', '["À la base de l’objet","À la surface supérieure","Au point de contact avec le sol","Au centre de gravité de l’objet"]'::jsonb, 3, 'Le poids s’applique au centre de gravité de l’objet ; il est vertical et dirigé vers le bas.', 4)
  ) AS v(id, slug, level, chapter, question, kind, options, correct_index, explanation, rang)
  JOIN public.subjects s ON s.slug = v.slug
  JOIN public.chapters c ON c.subject_id = s.id AND c.level = v.level AND c.title = v.chapter
  JOIN LATERAL (
    SELECT qz.id FROM public.lessons l
      JOIN public.quizzes qz ON qz.lesson_id = l.id
     WHERE l.chapter_id = c.id
     ORDER BY l.position, qz.id
     LIMIT 1
  ) qz ON true
ON CONFLICT (id) DO NOTHING;

